// views/inline-runner-modal.ts — Phase 54: Inline protocol display mode
// A floating, non-blocking DOM host for inline protocol runs over the active note.
// NOT an Obsidian Modal subclass — plain class managing its own DOM element.
import { App, TFile, Notice, setIcon } from 'obsidian';
import type RadiProtocolPlugin from '../main';
import { ProtocolRunner } from '../runner/protocol-runner';
import { GraphValidator } from '../graph/graph-validator';
import type { ProtocolGraph, AnswerNode } from '../graph/graph-model';
import type { RunnerState } from '../runner/runner-state';
import { SnippetTreePicker } from './snippet-tree-picker';
import { SnippetFillInModal } from './snippet-fill-in-modal';
import { SnippetEditorModal } from './snippet-editor-modal';
import { renderLoopPicker } from '../runner/render/render-loop-picker';
import { renderQuestionAtNode } from '../runner/render/render-question';
import { renderSnippetPicker } from '../runner/render/render-snippet-picker';
import { renderCompleteHeading } from '../runner/render/render-complete';
import { renderErrorList } from '../runner/render/render-error';
import { createButton } from '../utils/dom-helpers';
import { CSS_CLASS } from '../constants/css-classes';
import {
  isFullSnippetPath,
  renderSnippetFillLoading,
  renderSnippetFillNotFound,
} from '../runner/render/render-snippet-fill';
import type { InlineRunnerLayout } from '../settings';
import { InlineRunnerLayoutManager } from './inline-runner-layout';

// Re-export clamp functions for backward compatibility (tests import from this module).
export { clampInlineRunnerPosition, clampInlineRunnerLayout } from './inline-runner-layout';

/**
 * InlineRunnerModal — floating panel that hosts the Runner UI over an active note.
 *
 * Lifecycle:
 *   const modal = new InlineRunnerModal(app, plugin, canvasPath, targetNote);
 *   modal.open();   // parses canvas, starts runner, shows panel
 *   modal.close();  // unsubscribes, removes from DOM
 */
export class InlineRunnerModal {
  private readonly app: App;
  private readonly plugin: RadiProtocolPlugin;
  private readonly targetNote: TFile;
  private readonly startNodeId: string | undefined;

  private containerEl: HTMLElement | null = null;
  private headerEl: HTMLElement | null = null;
  private progressFillEl: HTMLElement | null = null;
  private progressTextEl: HTMLElement | null = null;
  private contentEl: HTMLElement | null = null;
  private actionsEl: HTMLElement | null = null;
  private footerBtnRowEl: HTMLElement | null = null;

  private runner: ProtocolRunner;
  private readonly validator: GraphValidator;
  private graph: ProtocolGraph | null = null;
  private canvasFilePath: string | null = null;
  private selfCheckItems: string[] = [];
  private selfCheckEnabled = false;

  private activeFileEventRef: import('obsidian').EventRef | null = null;
  private fileDeleteEventRef: import('obsidian').EventRef | null = null;
  private isHidden = false;
  private openedSuccessfully = false;

  private snippetTreePicker: SnippetTreePicker | null = null;
  private resizeObserver: ResizeObserver | null = null;
  private workspaceLayoutRef: import('obsidian').EventRef | null = null;
  private layoutManager: InlineRunnerLayoutManager | null = null;

  /** Phase 59 INLINE-FIX-05: tracks the active fill-in modal so close() can dispose it. */
  private fillModal: SnippetFillInModal | null = null;

  /** Phase 59 INLINE-FIX-05: gate flag — when true, D1 handleActiveLeafChange skips hide/show
 *  to prevent the inline container from disappearing while SnippetFillInModal is active. */
  private isFillModalOpen = false;

  private boundKeyHandler: ((e: KeyboardEvent) => void) | null = null;

  /** Phase 2 — create-snippet-from-selection footer button + selection listener. */
  private createSnippetBtnEl: HTMLButtonElement | null = null;
  private boundSelectionHandler: (() => void) | null = null;

  constructor(
    app: App,
    plugin: RadiProtocolPlugin,
    canvasFilePath: string,
    targetNote: TFile,
    startNodeId?: string,
  ) {
    this.app = app;
    this.plugin = plugin;
    this.canvasFilePath = canvasFilePath;
    this.targetNote = targetNote;
    this.startNodeId = startNodeId;
    // Phase 84 (I18N-02): inject translator so runtime / validator messages follow the active locale.
    this.runner = new ProtocolRunner({
      defaultSeparator: this.plugin.settings.textSeparator,
      t: this.plugin.i18n.t.bind(this.plugin.i18n),
    });
    this.validator = new GraphValidator({
      snippetFileProbe: (absPath) => this.app.vault.getAbstractFileByPath(absPath) !== null,
      snippetFolderPath: this.plugin.settings.snippetFolderPath,
      t: this.plugin.i18n.t.bind(this.plugin.i18n),
    });
  }

  // ── Phase 85 INLINE-MULTI-01 — Registry accessors ────────────────────────

  /** Identifier for the protocol file driving this runner. */
  getCanvasFilePath(): string | null {
    return this.canvasFilePath;
  }

  /** The markdown note this runner appends answers/snippets into. */
  getTargetNote(): TFile {
    return this.targetNote;
  }

  isOpen(): boolean {
    return this.openedSuccessfully && this.containerEl !== null;
  }

  /** Bring an already-open inline runner to the foreground.
   *  Re-appends the container to document.body (so it stacks above sibling
   *  runners) and clears the D1 `is-hidden` class if previously hidden. */
  focus(): void {
    if (this.containerEl === null) return;
    document.body.appendChild(this.containerEl);
    this.containerEl.removeClass('is-hidden');
    this.isHidden = false;
  }

  // ── Lifecycle ─────────────────────────────────────────────────────────────

  async open(): Promise<void> {
    console.debug('[RadiProtocol] InlineRunnerModal.open()', this.canvasFilePath);

    // Build DOM shell
    this.buildContainer();

    // Parse and validate .rp.json protocol file.
    const protocolPath = this.canvasFilePath!;
    const file = this.app.vault.getAbstractFileByPath(protocolPath);
    if (!(file instanceof TFile)) {
      const reason = this.plugin.i18n.t('inlineRunner.protocolFileNotFound', { path: protocolPath });
      console.warn('[RadiProtocol] InlineRunnerModal.open() failed:', reason);
      new Notice(reason);
      this.close();
      return;
    }

    let content: string;
    try {
      content = await this.app.vault.read(file);
    } catch {
      const reason = this.plugin.i18n.t('inlineRunner.couldNotReadProtocol', { path: protocolPath });
      console.warn('[RadiProtocol] InlineRunnerModal.open() failed:', reason);
      new Notice(reason);
      this.close();
      return;
    }

    this.selfCheckItems = [];
    this.selfCheckEnabled = false;
    try {
      const rawDoc = JSON.parse(content) as { selfCheckItems?: unknown; selfCheckEnabled?: unknown };
      if (Array.isArray(rawDoc.selfCheckItems)) {
        this.selfCheckItems = rawDoc.selfCheckItems
          .filter((item): item is string => typeof item === 'string')
          .map(item => item.trim())
          .filter(item => item.length > 0);
      }
      if (rawDoc.selfCheckEnabled === true) this.selfCheckEnabled = true;
    } catch {
      this.selfCheckItems = [];
      this.selfCheckEnabled = false;
    }

    const parseResult = this.plugin.protocolDocumentParser.parse(content, protocolPath);
    if (!parseResult.success) {
      console.warn('[RadiProtocol] InlineRunnerModal.open() parse failed:', parseResult.error);
      new Notice(parseResult.error);
      this.close();
      return;
    }

    const validationErrors = this.validator.validate(parseResult.graph);
    if (validationErrors.length > 0) {
      console.warn('[RadiProtocol] InlineRunnerModal.open() validation failed:', validationErrors);
      new Notice(validationErrors.join('\n'));
      this.close();
      return;
    }

    this.graph = parseResult.graph;
    this.runner.start(this.graph, this.startNodeId);
    this.render();
    this.openedSuccessfully = true;

    // D1: freeze/resume on note switch
    this.activeFileEventRef = this.app.workspace.on('active-leaf-change', () => {
      this.handleActiveLeafChange();
    });

    // D2: close when target note is deleted
    this.fileDeleteEventRef = this.app.vault.on('delete', (deletedFile) => {
      if (deletedFile instanceof TFile && deletedFile.path === this.targetNote.path) {
        this.handleTargetNoteDeleted();
      }
    });

    // Initial visibility check
    this.handleActiveLeafChange();

    // Phase 85 INLINE-MULTI-02: cascade-or-default position decision.
    this.layoutManager!.applyInitialLayout();

    // Re-clamp on layout changes without resetting to note-width anchoring.
    this.workspaceLayoutRef = this.app.workspace.on('layout-change', () => {
      void this.layoutManager!.reclampCurrentPosition(true);
    });
    this.layoutManager!.startWindowResizeListener();

    // Phase 67 D-04 / D-07: debounced save on resize-end + .is-resizing lifecycle.
    if (this.containerEl !== null) {
      this.resizeObserver = new ResizeObserver(() => this.layoutManager!.handleResizeTick());
      this.resizeObserver.observe(this.containerEl);
    }

    // Keyboard shortcuts: Ctrl/Alt+Left = step back, Ctrl/Alt+Right = redo, Escape = close
    this.boundKeyHandler = (e: KeyboardEvent) => this.handleKeydown(e);
    this.containerEl?.addEventListener('keydown', this.boundKeyHandler);

    // Phase 2 — track text selection inside contentEl to enable/disable the
    // create-snippet-from-selection footer button. mouseup covers drag-selection;
    // selectionchange covers keyboard Shift+Arrow selection.
    this.boundSelectionHandler = () => this.updateCreateSnippetButtonState();
    this.contentEl?.addEventListener('mouseup', this.boundSelectionHandler);
    document.addEventListener('selectionchange', this.boundSelectionHandler);
  }

  close(): void {
    console.debug('[RadiProtocol] InlineRunnerModal.close()');
    this.openedSuccessfully = false;

    // Unmount picker if active
    if (this.snippetTreePicker !== null) {
      this.snippetTreePicker.unmount();
      this.snippetTreePicker = null;
    }

    // Phase 59 INLINE-FIX-05: ensure fill-in modal is closed if inline closes first.
    // Single .close() call here — handleSnippetFill's finally does NOT call .close()
    // (modal self-closed when result resolved). This close() runs only when inline
    // closes BEFORE the modal resolves (orphan scenario).
    if (this.fillModal !== null) {
      this.fillModal.close();
      this.fillModal = null;
    }
    this.isFillModalOpen = false;

    // Unsubscribe event listeners
    if (this.boundKeyHandler !== null && this.containerEl !== null) {
      this.containerEl.removeEventListener('keydown', this.boundKeyHandler);
    }
    this.boundKeyHandler = null;

    // Phase 2 — detach selection listeners and release DOM refs (parity with boundKeyHandler).
    // Runs BEFORE contentEl/containerEl are nulled below so removeEventListener still sees the node.
    if (this.boundSelectionHandler !== null) {
      this.contentEl?.removeEventListener('mouseup', this.boundSelectionHandler);
      document.removeEventListener('selectionchange', this.boundSelectionHandler);
      this.boundSelectionHandler = null;
    }
    this.createSnippetBtnEl = null;
    if (this.activeFileEventRef !== null) {
      this.app.workspace.offref(this.activeFileEventRef);
      this.activeFileEventRef = null;
    }
    if (this.fileDeleteEventRef !== null) {
      this.app.vault.offref(this.fileDeleteEventRef);
      this.fileDeleteEventRef = null;
    }
    if (this.workspaceLayoutRef !== null) {
      this.app.workspace.offref(this.workspaceLayoutRef);
      this.workspaceLayoutRef = null;
    }
    if (this.resizeObserver !== null) {
      this.resizeObserver.disconnect();
      this.resizeObserver = null;
    }
    // Phase 67: defensive resize-state cleanup delegated to layout manager.
    if (this.layoutManager !== null) {
      this.layoutManager.destroy();
      this.layoutManager = null;
    }

    // Phase 85 INLINE-MULTI-01: unregister from the plugin's registry. Computed
    // BEFORE we null out canvasFilePath/containerEl so the key is still derivable.
    if (this.canvasFilePath !== null) {
      const key = `${this.canvasFilePath}#${this.targetNote.path}`;
      this.plugin.unregisterInlineRunner(key);
    }

    // Remove from DOM
    if (this.containerEl !== null) {
      this.containerEl.remove();
      this.containerEl = null;
    }

    this.headerEl = null;
    this.progressFillEl = null;
    this.progressTextEl = null;
    this.contentEl = null;
    this.actionsEl = null;
    this.footerBtnRowEl = null;
    this.graph = null;
  }

  // ── DOM Building ──────────────────────────────────────────────────────────

  private buildContainer(): void {
    const container = document.body.createDiv({ cls: 'rp-inline-runner-container' });
    this.containerEl = container;

    // Create layout manager for position/drag/resize.
    this.layoutManager = new InlineRunnerLayoutManager({
      containerEl: container,
      getSavedLayout: () => this.plugin.getInlineRunnerPosition(),
      saveLayout: (layout) => this.plugin.saveInlineRunnerPosition(layout),
      getOpenLayouts: () => this.plugin.getOpenInlineRunners().map(r => r.getAppliedLayout()),
    });

    // Header — drag handle + progress bar at top of modal
    const header = container.createDiv({ cls: 'rp-inline-runner-header' });
    this.headerEl = header;
    this.layoutManager.enableDragging(header);

    // Progress bar — top of modal, inside header
    const progress = header.createDiv({ cls: 'rp-inline-runner-progress', attr: { role: 'progressbar', 'aria-valuemin': '0', 'aria-valuemax': '100' } });
    const progressTrack = progress.createDiv({ cls: 'rp-inline-runner-progress-track' });
    this.progressFillEl = progressTrack.createDiv({ cls: 'rp-inline-runner-progress-fill' });
    this.progressTextEl = progress.createDiv({ cls: 'rp-inline-runner-progress-text' });

    // Content area — scrollable text (top half of modal)
    const content = container.createDiv({ cls: 'rp-inline-runner-content' });
    this.contentEl = content;

    // Actions zone — buttons anchored from top, scrollable if overflow (bottom half)
    const actions = container.createDiv({ cls: 'rp-inline-runner-actions' });
    this.actionsEl = actions;

    // Footer — close button (left) + Back/Skip (right)
    const footer = container.createDiv({ cls: 'rp-inline-runner-footer' });
    const footerBtnRow = footer.createDiv({ cls: 'rp-inline-runner-footer-btn-row' });
    this.footerBtnRowEl = footerBtnRow;

    // Close button — left side of footer row (square icon button)
    const closeBtn = footerBtnRow.createEl('button', { cls: 'rp-inline-runner-close-btn rp-runner-icon-btn' });
    setIcon(closeBtn, 'x');
    closeBtn.setAttribute('aria-label', this.plugin.i18n.t('protocolRunner.closeProtocol'));
    closeBtn.addEventListener('click', () => {
      this.close();
    });
  }

  // ── Rendering ─────────────────────────────────────────────────────────────

  private calculateProgressPercent(state: RunnerState): number {
    if (this.graph === null) return 0;
    if (state.status === 'complete') return 100;
    if (state.status === 'idle' || state.status === 'error') return 0;

    const currentNodeId = state.status === 'at-node' ? state.currentNodeId : state.nodeId;
    const globalDistances = this.calculateShortestDistances(this.graph.startNodeId);
    const globalMaxDistance = Math.max(1, ...globalDistances.values());
    const sessionStartNodeId = this.startNodeId ?? this.graph.startNodeId;
    const baselineDistance = globalDistances.get(sessionStartNodeId) ?? 0;
    const baselinePercent = Math.round((baselineDistance / globalMaxDistance) * 99);

    const sessionDistances = this.calculateShortestDistances(sessionStartNodeId);
    const currentSessionDistance = sessionDistances.get(currentNodeId);
    if (currentSessionDistance === undefined) return Math.min(99, Math.max(0, baselinePercent));

    const sessionMaxDistance = Math.max(1, ...sessionDistances.values());
    const remainingPercent = 99 - baselinePercent;
    const sessionPercent = Math.round((currentSessionDistance / sessionMaxDistance) * remainingPercent);
    return Math.min(99, Math.max(0, baselinePercent + sessionPercent));
  }

  private calculateShortestDistances(startNodeId: string): Map<string, number> {
    const distances = new Map<string, number>();
    if (this.graph === null) return distances;

    const queue: string[] = [startNodeId];
    distances.set(startNodeId, 0);

    while (queue.length > 0) {
      const current = queue.shift();
      if (current === undefined) break;
      const currentDistance = distances.get(current) ?? 0;
      for (const next of this.graph.adjacency.get(current) ?? []) {
        if (distances.has(next)) continue;
        distances.set(next, currentDistance + 1);
        queue.push(next);
      }
    }

    return distances;
  }

  private updateProgress(state: RunnerState): void {
    if (this.progressFillEl === null || this.progressTextEl === null) return;
    const percent = this.calculateProgressPercent(state);
    this.progressFillEl.style.width = `${percent}%`;
    this.progressTextEl.setText(`${percent}%`);
    const progressEl = this.containerEl?.querySelector('.rp-inline-runner-progress');
    progressEl?.setAttribute('aria-valuenow', String(percent));
    progressEl?.setAttribute('aria-label', this.plugin.i18n.t('protocolRunner.progressLabel', { percent: String(percent) }));
  }

  private render(): void {
    if (this.contentEl === null) return;

    // Unmount picker if state has left awaiting-snippet-pick
    const state = this.runner.getState();
    this.updateProgress(state);
    if (this.snippetTreePicker !== null && state.status !== 'awaiting-snippet-pick') {
      this.snippetTreePicker.unmount();
      this.snippetTreePicker = null;
    }

    this.contentEl.empty();
    if (this.actionsEl !== null) this.actionsEl.empty();

    // Toggle layout state class on container:
    //   rp-state-actions      → split layout: content 50% + actions 50% (at-node, awaiting-loop-pick)
    //   rp-state-content-only → full-height content, actions hidden (all other states)
    const actionsStates: RunnerState['status'][] = ['at-node', 'awaiting-loop-pick'];
    const hasActions = actionsStates.includes(state.status);
    if (this.containerEl !== null) {
      this.containerEl.toggleClass('rp-state-actions', hasActions);
      this.containerEl.toggleClass('rp-state-content-only', !hasActions);
    }

    // Recreate footer-row children (close btn destroyed by empty, must re-add)
    if (this.footerBtnRowEl !== null) {
      this.footerBtnRowEl.empty();

      // Phase 2 — left group holds close + create-snippet-from-selection.
      const leftGroup = this.footerBtnRowEl.createDiv({ cls: 'rp-runner-footer-left' });

      // Close button — always present on the left
      const closeBtn = leftGroup.createEl('button', { cls: 'rp-inline-runner-close-btn rp-runner-icon-btn' });
      setIcon(closeBtn, 'x');
      closeBtn.setAttribute('aria-label', this.plugin.i18n.t('protocolRunner.closeProtocol'));
      closeBtn.addEventListener('click', () => {
        this.close();
      });

      // Create-snippet-from-selection — always visible, disabled until contentEl has a selection.
      const createSnippetBtn = leftGroup.createEl('button', {
        cls: 'rp-inline-runner-create-snippet-btn rp-runner-icon-btn',
        attr: { 'aria-label': this.plugin.i18n.t('protocolRunner.createSnippetFromSelection') },
      });
      setIcon(createSnippetBtn, 'file-plus');
      createSnippetBtn.disabled = true;
      createSnippetBtn.addEventListener('click', () => {
        void this.handleCreateSnippetFromSelection();
      });
      this.createSnippetBtnEl = createSnippetBtn;
      // Re-evaluate against the live selection so an existing selection at render time enables it.
      this.updateCreateSnippetButtonState();
    }

    switch (state.status) {
      case 'idle': {
        this.contentEl.createEl('p', {
          text: this.plugin.i18n.t('protocolRunner.starting'),
          cls: CSS_CLASS.EMPTY_STATE_BODY,
        });
        break;
      }

      case 'at-node': {
        const result = renderQuestionAtNode(
          this.contentEl,
          this.actionsEl!,
          this.graph,
          state,
          {
            bindClick: (el, handler) => el.addEventListener('click', handler),
            renderError: (messages) => this.renderError(this.contentEl!, messages),
            onChooseAnswer: (answerNode) => this.handleAnswerClick(answerNode),
            onChooseSnippetBranch: (snippetNode, isFileBound) => {
              if (isFileBound) {
                const snippetPath = snippetNode.radiprotocol_snippetPath as string;
                this.runner.pickFileBoundSnippet(state.currentNodeId, snippetNode.id, snippetPath);
              } else {
                this.runner.chooseSnippetBranch(snippetNode.id);
              }
              this.render();
            },
          },
        );
        if (result === 'error') return;
        if (result === 'not-question') {
          this.contentEl.createEl('p', {
            text: this.plugin.i18n.t('protocolRunner.processing'),
            cls: CSS_CLASS.EMPTY_STATE_BODY,
          });
        }

        // Footer icon buttons: Back + Skip (only when question has answers)
        if (this.footerBtnRowEl !== null && this.graph !== null) {
          const node = this.graph.nodes.get(state.currentNodeId);
          if (node !== undefined && node.kind === 'question') {
            const neighborIds = this.graph.adjacency.get(state.currentNodeId) ?? [];
            const hasAnswers = neighborIds.some(
              (nid) => this.graph!.nodes.get(nid)?.kind === 'answer',
            );
            this.renderFooterIcons(state.canStepBack, hasAnswers && typeof this.runner.skip === 'function', state.canRedo);
          }
        }
        break;
      }

      case 'awaiting-snippet-pick': {
        this.contentEl.createEl('p', {
          text: this.plugin.i18n.t('protocolRunner.loadingSnippets'),
          cls: CSS_CLASS.EMPTY_STATE_BODY,
        });
        void this.mountSnippetPicker(state, this.contentEl);
        break;
      }

      case 'awaiting-loop-pick': {
        const rendered = renderLoopPicker(
          this.contentEl,
          this.actionsEl!,
          this.graph,
          state,
          {
            bindClick: (el, handler) => el.addEventListener('click', handler),
            renderError: (messages) => this.renderError(this.contentEl!, messages),
            onChooseLoopBranch: (edge, isExit) => this.handleLoopBranchClick(edge, isExit),
          },
        );
        if (!rendered) return;

        // Footer icon buttons: Back only (no Skip in loop picker)
        if (this.footerBtnRowEl !== null) {
          this.renderFooterIcons(state.canStepBack, false, state.canRedo);
        }
        break;
      }

      case 'awaiting-snippet-fill': {
        renderSnippetFillLoading(this.contentEl);
        void this.handleSnippetFill(state.snippetId, this.contentEl);
        break;
      }

      case 'complete': {
        if (!this.selfCheckEnabled) {
          const scheduleClose = typeof window !== 'undefined' ? window.setTimeout.bind(window) : globalThis.setTimeout;
          scheduleClose(() => this.close(), 0);
          break;
        }
        if (this.selfCheckItems.length === 0) {
          const scheduleClose = typeof window !== 'undefined' ? window.setTimeout.bind(window) : globalThis.setTimeout;
          scheduleClose(() => this.close(), 0);
          break;
        }
        this.renderSelfCheckCompletion(this.contentEl);
        break;
      }

      case 'error': {
        this.renderError(this.contentEl, [state.message]);
        break;
      }

      default: {
        const _exhaustive: never = state;
        void _exhaustive;
        break;
      }
    }
  }

  /** Render Back/Redo/Skip icon buttons into the footer row (after close btn). */
  private renderFooterIcons(showBack: boolean, showSkip: boolean, showRedo: boolean): void {
    if (this.footerBtnRowEl === null) return;
    if (!showBack && !showSkip && !showRedo) return;

    const t = this.plugin.i18n.t.bind(this.plugin.i18n);
    // Container for Back+Redo+Skip, pushed right via justify-content: flex-end
    const iconsGroup = this.footerBtnRowEl.createDiv({ cls: 'rp-runner-footer-row' });
    if (showBack) {
      const backBtn = createButton(iconsGroup, {
        cls: 'rp-step-back-btn rp-runner-icon-btn',
        attr: { 'aria-label': t('protocolRunner.stepBack') },
      });
      setIcon(backBtn, 'arrow-left');
      // Phase 66 D-01/D-02/D-03: visual half of double-click guard
      backBtn.addEventListener('click', () => {
        backBtn.disabled = true;
        this.runner.stepBack();
        this.render();
      });
    }
    if (showRedo) {
      const redoBtn = createButton(iconsGroup, {
        cls: 'rp-step-redo-btn rp-runner-icon-btn',
        attr: { 'aria-label': t('protocolRunner.stepRedo') },
      });
      setIcon(redoBtn, 'redo');
      redoBtn.addEventListener('click', () => {
        redoBtn.disabled = true;
        this.runner.redo();
        this.render();
      });
    }
    if (showSkip) {
      const skipBtn = createButton(iconsGroup, {
        cls: 'rp-skip-btn rp-runner-icon-btn',
        attr: { 'aria-label': t('protocolRunner.stepSkip') },
      });
      setIcon(skipBtn, 'skip-forward');
      skipBtn.addEventListener('click', () => {
        this.runner.skip();
        this.render();
      });
    }
  }

  private renderSelfCheckCompletion(container: HTMLElement): void {
    renderCompleteHeading(container);
    const checklist = container.createDiv({ cls: 'rp-inline-runner-self-check' });
    checklist.createEl('h4', { text: this.plugin.i18n.t('selfCheck.title') });
    const checked = new Set<number>();
    const updateCompletion = () => {
      if (checked.size === this.selfCheckItems.length) this.close();
    };
    this.selfCheckItems.forEach((item, index) => {
      const label = checklist.createEl('label', { cls: 'rp-inline-runner-self-check-item' });
      const checkbox = label.createEl('input', { type: 'checkbox' });
      label.createSpan({ text: item });
      checkbox.addEventListener('change', () => {
        if (checkbox.checked) checked.add(index);
        else checked.delete(index);
        updateCompletion();
      });
    });

  }

  // ── Event Handlers ────────────────────────────────────────────────────────

  /** D1: freeze/resume — hide modal when active note is not the target note. */
  private handleActiveLeafChange(): void {
    if (this.containerEl === null) return;

    // Phase 59 INLINE-FIX-05 / Pitfall 3: while SnippetFillInModal is open, focus
    // may transition to the stacked modal and fire active-leaf-change. Skipping the
    // D1 hide/show logic here keeps the inline container visible under the modal
    // so the user sees context while filling placeholders, and avoids a hide→show
    // flicker when the modal closes.
    if (this.isFillModalOpen) return;

    const activeFile = this.app.workspace.getActiveFile();
    const isTargetActive = activeFile !== null && activeFile.path === this.targetNote.path;

    // Check if target note has any open leaves by iterating all leaves
    let targetHasOpenLeaves = false;
    this.app.workspace.iterateAllLeaves((leaf) => {
      const view = leaf.view;
      if ('file' in view && view.file instanceof TFile) {
        if (view.file.path === this.targetNote.path) {
          targetHasOpenLeaves = true;
        }
      }
    });

    if (!targetHasOpenLeaves) {
      // D2: target note tab closed — end the run
      this.close();
      return;
    }

    if (isTargetActive) {
      if (this.isHidden) {
        this.containerEl.removeClass('is-hidden');
        this.isHidden = false;
      }
    } else {
      if (!this.isHidden) {
        this.containerEl.addClass('is-hidden');
        this.isHidden = true;
      }
    }
  }

  /** D2: target note was deleted — close the modal. */
  private handleTargetNoteDeleted(): void {
    console.debug('[RadiProtocol] InlineRunnerModal: target note deleted, closing');
    this.close();
  }

  private handleKeydown(e: KeyboardEvent): void {
    const target = e.target as HTMLElement | null;
    if (target !== null && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA')) {
      return;
    }

    if (e.key === 'Escape') {
      e.preventDefault();
      this.close();
      return;
    }

    if ((e.ctrlKey || e.altKey) && e.key === 'ArrowLeft') {
      e.preventDefault();
      this.runner.stepBack();
      this.render();
      return;
    }

    if ((e.ctrlKey || e.altKey) && e.key === 'ArrowRight') {
      e.preventDefault();
      this.runner.redo();
      this.render();
      return;
    }
  }

  /** Phase 2 — Return the current selection's text iff its anchor node is contained
   *  in contentEl. Selections outside the runner (e.g. in the note behind it) return ''. */
  private getSelectedContentText(): string {
    if (this.contentEl === null) return '';
    if (typeof window === 'undefined') return '';
    const sel = window.getSelection();
    if (sel === null || sel.isCollapsed) return '';
    const anchorNode = sel.anchorNode;
    if (anchorNode === null) return '';

    const contentEl = this.contentEl;
    let node: Node | null = anchorNode;
    while (node !== null) {
      if (node === contentEl) return sel.toString();
      node = node.parentNode;
    }
    return '';
  }

  /** Phase 2 — Enable/disable the create-snippet button based on the live selection. */
  private updateCreateSnippetButtonState(): void {
    if (this.createSnippetBtnEl === null) return;
    this.createSnippetBtnEl.disabled = this.getSelectedContentText().length === 0;
  }

  /** Phase 2 — Capture the selection, open SnippetEditorModal in create mode pre-filled
   *  with the selected text, await its result. The inline runner stays open underneath
   *  (SnippetEditorModal mounts to document.body and stacks above the runner overlay).
   *  Defensive guard: no-op when the selection is empty (covers disabled-button edge). */
  private async handleCreateSnippetFromSelection(): Promise<void> {
    const template = this.getSelectedContentText();
    if (template.length === 0) return;
    const modal = new SnippetEditorModal(this.app, this.plugin, {
      mode: 'create',
      initialFolder: this.plugin.settings.snippetFolderPath,
      initialTemplate: template,
    });
    modal.open();
    await modal.result;
  }

  /** Phase 85 INLINE-MULTI-02: public so the cascade logic in another modal's
   *  open() can read this instance's current applied position. */
  getAppliedLayout(): InlineRunnerLayout | null {
    if (this.layoutManager === null) return null;
    return this.layoutManager.getAppliedLayout();
  }

  /** Delegates to InlineRunnerLayoutManager.restoreOrDefaultPosition(). */
  restoreOrDefaultPosition(): void {
    this.layoutManager?.restoreOrDefaultPosition();
  }

  /** Delegates to InlineRunnerLayoutManager.applyInitialLayout(). */
  applyInitialLayout(): void {
    this.layoutManager?.applyInitialLayout();
  }

  /** Delegates to InlineRunnerLayoutManager.reclampCurrentPosition(). */
  async reclampCurrentPosition(persistIfChanged: boolean): Promise<void> {
    await this.layoutManager?.reclampCurrentPosition(persistIfChanged);
  }

  /** Delegates to InlineRunnerLayoutManager.handleResizeTick().
   *  Exposed for ResizeObserver test harness in inline-runner-layout.test.ts. */
  handleResizeTick(): void {
    this.layoutManager?.handleResizeTick();
  }

  /** Resolve the textSeparator enum to its actual string value. */
  private resolveSeparator(): string {
    const sep = this.plugin.settings.textSeparator;
    return sep === 'newline' ? '\n' : ' ';
  }

  /** Handle answer button click — append answer to note and advance. */
  private async handleAnswerClick(answerNode: AnswerNode): Promise<void> {
    const stateBefore = this.runner.getState();
    const beforeText = this.extractAccumulatedText(stateBefore);

    this.runner.chooseAnswer(answerNode.id);

    const stateAfter = this.runner.getState();
    const afterText = this.extractAccumulatedText(stateAfter);

    if (afterText.length > beforeText.length) {
      // WR-01: defensive check — text should only grow (append-only invariant)
      if (!afterText.startsWith(beforeText)) {
        console.warn('[RadiProtocol] Text changed non-monotonically, skipping append');
        this.render();
        return;
      }
      const appendedText = afterText.slice(beforeText.length);
      await this.appendAnswerToNote(appendedText);
    }

    this.render();
  }

  /** Append text to the end of the target note. The delta already contains
   *  separators from the accumulator, but Obsidian adds a trailing newline
   *  to files on save. If the note already ends with the separator char and
   *  the delta starts with it, strip the leading separator from the delta
   *  to avoid duplication.
   *  CR-02: Protected by insertMutex to prevent read-modify-write races
   *  with concurrent vault.modify calls (e.g., user edits, other plugins). */
  private async appendAnswerToNote(text: string): Promise<void> {
    await this.plugin['insertMutex'].runExclusive(this.targetNote.path, async () => {
      const currentContent = await this.app.vault.read(this.targetNote);
      let toAppend = text;
      const sep = this.resolveSeparator();
      if (currentContent.endsWith(sep) && text.startsWith(sep)) {
        toAppend = text.slice(sep.length);
      }
      const newContent = currentContent + toAppend;
      await this.app.vault.modify(this.targetNote, newContent);
    });
  }

  /**
   * Phase 59 INLINE-FIX-04 — Accumulator-diff helper for snippet insert paths.
   *
   * Mirrors {@link handleAnswerClick}'s diff logic so snippet dispatch
   * sites can append the separator-applied delta (not raw snippet content) to the note.
   *
   * Contract: caller captures `beforeText` BEFORE calling `runner.completeSnippet(...)`.
   * After completeSnippet mutates the accumulator (applying the per-node or global
   * separator), this helper reads `afterText`, computes the delta, and pipes it through
   * the same `appendAnswerToNote` sink that the answer path uses — preserving the
   * `TextAccumulator.appendWithSeparator` first-chunk invariant.
   *
   * Non-monotonic accumulator growth (afterText does not start with beforeText) is
   * treated as a bug and logged via console.warn, mirroring WR-01 in handleAnswerClick.
   */
  private async appendDeltaFromAccumulator(beforeText: string): Promise<void> {
    const afterText = this.extractAccumulatedText(this.runner.getState());
    if (afterText.length <= beforeText.length) return;
    if (!afterText.startsWith(beforeText)) {
      console.warn('[RadiProtocol] Text changed non-monotonically, skipping append');
      return;
    }
    await this.appendAnswerToNote(afterText.slice(beforeText.length));
  }

  /** Handle loop branch click — append any traversed answer text to note. */
  private async handleLoopBranchClick(edge: import('../graph/graph-model').RPEdge, _isExit: boolean): Promise<void> {
    void _isExit;
    // Capture accumulated text before the branch choice
    const stateBefore = this.runner.getState();
    const beforeText = stateBefore.status === 'awaiting-loop-pick'
      ? stateBefore.accumulatedText
      : '';

    this.runner.chooseLoopBranch(edge.id);

    // After chooseLoopBranch, the runner may have advanced through answer/text-block nodes.
    // Capture the new accumulated text — the delta is what was appended by advanceThrough.
    const stateAfter = this.runner.getState();
    let afterText = '';
    if (stateAfter.status === 'at-node') {
      afterText = stateAfter.accumulatedText;
    } else if (stateAfter.status === 'awaiting-loop-pick') {
      afterText = stateAfter.accumulatedText;
    } else if (stateAfter.status === 'complete') {
      afterText = stateAfter.finalText;
    } else if (stateAfter.status === 'awaiting-snippet-pick') {
      afterText = stateAfter.accumulatedText;
    } else if (stateAfter.status === 'awaiting-snippet-fill') {
      afterText = stateAfter.accumulatedText;
    } else {
      // WR-02: unexpected state — preserve baseline to avoid spurious append
      console.warn('[RadiProtocol] Unexpected state after loop branch:', stateAfter.status);
      afterText = beforeText;
    }

    if (afterText.length > beforeText.length) {
      const appendedText = afterText.slice(beforeText.length);
      await this.appendAnswerToNote(appendedText);
    }

    this.render();
  }

  /** Extract accumulated text from any runner state. */
  private extractAccumulatedText(state: ReturnType<typeof this.runner.getState>): string {
    switch (state.status) {
      case 'at-node':
      case 'awaiting-loop-pick':
      case 'awaiting-snippet-pick':
      case 'awaiting-snippet-fill':
        return state.accumulatedText;
      case 'complete':
        return state.finalText;
      default:
        return '';
    }
  }



  /** Render snippet picker inline (Phase 51 D-06 pattern). */
  private async mountSnippetPicker(
    state: {
      status: 'awaiting-snippet-pick';
      nodeId: string;
      subfolderPath: string | undefined;
      accumulatedText: string;
      canStepBack: boolean;
      canRedo: boolean;
      undoStackSize: number;
    },
    questionZone: HTMLElement,
  ): Promise<void> {
    if (this.snippetTreePicker !== null) {
      this.snippetTreePicker.unmount();
      this.snippetTreePicker = null;
    }

    this.snippetTreePicker = renderSnippetPicker(questionZone, state, {
      app: this.app,
      snippetService: this.plugin.snippetService,
      rootPath: this.plugin.settings.snippetFolderPath,
      hostClass: CSS_CLASS.STP_INLINE_HOST,
      copy: {
        notFound: (relativePath) => this.plugin.i18n.t('inlineRunner.snippetNotFound', { path: relativePath }),
        validationError: (snippetPath, validationMessage) =>
          this.plugin.i18n.t('inlineRunner.snippetCannotBeUsed', { path: snippetPath, error: validationMessage }),
      },
      t: this.plugin.i18n.t.bind(this.plugin.i18n),
      bindClick: (el, handler) => el.addEventListener('click', handler),
      getCurrentNodeId: () => {
        const s = this.runner.getState();
        return s.status === 'awaiting-snippet-pick' ? s.nodeId : null;
      },
      // CR-01: detached-DOM guard for inline modal closures.
      isStillMounted: () =>
        this.containerEl !== null && document.body.contains(this.containerEl),
      // Inline modal re-renders before showing the error so the new picker
      // takes a fresh DOM, then writes the error into contentEl.
      presentAsyncError: (message) => {
        this.render();
        if (this.contentEl) {
          this.contentEl.createEl('p', {
            cls: CSS_CLASS.EMPTY_STATE_BODY,
            text: message,
          });
        }
      },
      onSnippetReady: (snippet) => this.handleSnippetPickerSelection(snippet),
      onBack: () => {
        if (this.snippetTreePicker !== null) {
          this.snippetTreePicker.unmount();
          this.snippetTreePicker = null;
        }
        this.runner.stepBack();
        this.render();
      },
      onRedo: () => {
        this.runner.redo();
        this.render();
      },
    });
  }

  /** Handle snippet picker selection — append to note and advance. */
  private async handleSnippetPickerSelection(snippet: import('../snippets/snippet-model').Snippet): Promise<void> {
    if (snippet.kind === 'json' && snippet.validationError !== null) {
      new Notice(this.plugin.i18n.t('inlineRunner.snippetCannotBeUsed', { path: snippet.path, error: snippet.validationError }));
      return;
    }

    const pickId = (snippet.kind === 'md' || snippet.kind === 'md-template') ? snippet.path : (snippet.id ?? snippet.name);
    this.runner.pickSnippet(pickId);

    if (snippet.kind === 'md') {
      // Phase 59 INLINE-FIX-04: capture baseline BEFORE completeSnippet so the
      // accumulator delta includes the resolved separator applied by
      // runner → TextAccumulator.appendWithSeparator. Raw snippet.content bypasses it.
      const beforeText = this.extractAccumulatedText(this.runner.getState());
      this.runner.completeSnippet(snippet.content);
      await this.appendDeltaFromAccumulator(beforeText);
      this.snippetTreePicker?.unmount();
      this.snippetTreePicker = null;
      this.render();
      return;
    }

    if (snippet.placeholders.length === 0) {
      // Phase 59 INLINE-FIX-04: same accumulator-diff pattern as MD arm above.
      const beforeText = this.extractAccumulatedText(this.runner.getState());
      this.runner.completeSnippet(snippet.template);
      await this.appendDeltaFromAccumulator(beforeText);
      this.snippetTreePicker?.unmount();
      this.snippetTreePicker = null;
      this.render();
      return;
    }

    // Snippet has placeholders — advance to awaiting-snippet-fill state
    this.render();
  }

  /**
   * Phase 59 INLINE-FIX-05 — Load snippet and dispatch fill-in modal (parity with sidebar).
   *
   * Reverses Phase 54 D6: instead of rendering an in-panel form via the old fill-in method,
   * this now instantiates the stacked SnippetFillInModal using the shared snippet-fill flow.
   * The modal mounts to document.body (via Obsidian Modal); the inline container stays
   * visible underneath (gated by isFillModalOpen in handleActiveLeafChange).
   */
  private async handleSnippetFill(snippetId: string, questionZone: HTMLElement): Promise<void> {
    const isPhase51FullPath = isFullSnippetPath(snippetId);
    const root = this.plugin.settings.snippetFolderPath;
    // WR-03: avoid double-prefixing when snippetId is already an absolute vault path
    const absPath = snippetId.startsWith(root + '/')
      ? snippetId
      : isPhase51FullPath
        ? `${root}/${snippetId}`
        : null; // determined below via extension trial

    let snippet = null as Awaited<ReturnType<typeof this.plugin.snippetService.load>>;
    // Try .json then .md when snippetId lacks extension (picker basename case).
    if (absPath !== null) {
      snippet = await this.plugin.snippetService.load(absPath);
    } else {
      snippet = await this.plugin.snippetService.load(`${root}/${snippetId}.json`);
      if (snippet === null) {
        snippet = await this.plugin.snippetService.load(`${root}/${snippetId}.md`);
      }
    }

    // Phase 59 INLINE-FIX-05: fallback scan for JSON snippets in subdirectories.
    // When a snippet was selected from a picker in a subdirectory, pickId is a
    // basename, so the direct path misses the subdirectory. Scan vault files
    // under the snippet root for a matching basename.
    if (snippet === null && !isPhase51FullPath) {
      // Try .json then .md in subdirectories.
      for (const ext of ['.json', '.md']) {
        const targetBasename = `${snippetId}${ext}`;
        const candidates = this.app.vault.getFiles().filter((f) => {
          if (!f.path.startsWith(root + '/')) return false;
          const parts = f.path.split('/');
          return parts[parts.length - 1]! === targetBasename;
        });
        if (candidates.length === 1) {
          snippet = await this.plugin.snippetService.load(candidates[0]!.path);
          if (snippet !== null) break;
        }
      }
    }

    if (snippet === null) {
      renderSnippetFillNotFound(questionZone, snippetId);
      return;
    }

    if (snippet.kind === 'json' && snippet.validationError !== null) {
      new Notice(this.plugin.i18n.t('inlineRunner.snippetCannotBeUsed', { path: snippet.path, error: snippet.validationError }));
      this.runner.stepBack();
      this.render();
      return;
    }

    // Capture accumulator baseline before any runner mutation, for separator-applied delta.
    const beforeText = this.extractAccumulatedText(this.runner.getState());

    if (snippet.kind === 'md') {
      if (isPhase51FullPath) {
        this.runner.completeSnippet(snippet.content);
        await this.appendDeltaFromAccumulator(beforeText);
        this.render();
        return;
      }
      // Legacy path — MD snippet via non-full-path id; treat as not-found.
      renderSnippetFillNotFound(questionZone, snippetId);
      return;
    }

    if (snippet.kind === 'md-template') {
      if (snippet.placeholders.length === 0) {
        this.runner.completeSnippet(snippet.template);
        await this.appendDeltaFromAccumulator(beforeText);
        this.render();
        return;
      }
      // md-template with placeholders — open the stacked fill-in modal.
      const modal = new SnippetFillInModal(this.app, snippet, this.plugin.i18n.t.bind(this.plugin.i18n));
      this.fillModal = modal;
      this.isFillModalOpen = true;
      modal.open();
      let rendered: string | null;
      try {
        rendered = await modal.result;
      } finally {
        this.isFillModalOpen = false;
        this.fillModal = null;
      }
      if (rendered !== null) {
        this.runner.completeSnippet(rendered);
      } else {
        this.runner.completeSnippet('');
      }
      await this.appendDeltaFromAccumulator(beforeText);
      this.render();
      return;
    }

    if (snippet.placeholders.length === 0) {
      this.runner.completeSnippet(snippet.template);
      await this.appendDeltaFromAccumulator(beforeText);
      this.render();
      return;
    }

    // JSON with placeholders — open the stacked fill-in modal (parity with sidebar).
    // Phase 54 D6 is reversed: the in-panel fill-in form is gone.
    const modal = new SnippetFillInModal(this.app, snippet, this.plugin.i18n.t.bind(this.plugin.i18n));
    this.fillModal = modal;
    this.isFillModalOpen = true;
    modal.open();
    let rendered: string | null;
    try {
      rendered = await modal.result;
    } finally {
      // Clear flags. DO NOT call modal.close() here — the modal self-closed when its
      // result promise resolved (submit/cancel/escape all trigger close + resolve inside
      // SnippetFillInModal). Double-closing would fire duplicate onClose handlers.
      this.isFillModalOpen = false;
      this.fillModal = null;
    }
    if (rendered !== null) {
      this.runner.completeSnippet(rendered);
    } else {
      // D-11 parity with sidebar: cancel/escape → completeSnippet('') advances runner.
      this.runner.completeSnippet('');
    }
    await this.appendDeltaFromAccumulator(beforeText);
    this.render();
  }

  /** Render error state. */
  private renderError(zone: HTMLElement, errors: string[]): void {
    zone.empty();
    const errorPanel = zone.createDiv({ cls: 'rp-error-panel' });
    renderErrorList(errorPanel, errors, { titleClass: CSS_CLASS.ERROR_TITLE });
  }
}

// snippets/snippet-model.ts
// Pure module — zero Obsidian API imports (NFR-01)

import { defaultT, type Translator } from '../i18n';

export interface SnippetPlaceholder {
  id: string;
  label: string;
  /** Phase 52 D-01: union narrowed from 4 to 2. 'number' and 'multi-choice' removed. */
  type: 'free-text' | 'choice';
  /** Predefined options for 'choice' type (D-06) */
  options?: string[];
  /**
   * Phase 52 D-02: separator between values when >1 choice option selected.
   * Default: ', '. Renamed from legacy `joinSeparator`. Applies to unified
   * choice (single or multi-select).
   */
  separator?: string;
}

/**
 * Phase 32 (D-01): JSON snippet variant of the Snippet discriminated union.
 * Replaces the legacy `SnippetFile` interface; `SnippetFile` is retained below
 * as a type alias to minimize callsite churn during the phase 32 refactor.
 *
 * Identity (D-02): the full vault-relative `path` (including `.json`
 * extension) is the source of truth. The deprecated `id` field may still
 * appear in v1.4-era JSON files on disk and is tolerated on the type for
 * compatibility, but it is ignored at runtime — basename is authoritative.
 *
 * Phase 52 (D-03): non-optional `validationError` field. Non-null means the
 * file on disk declared a removed placeholder type ('number', 'multichoice',
 * 'multi-choice') or a 'choice' placeholder with invalid options. Consumers
 * MUST check before rendering in Editor or Runner — see SnippetEditorModal
 * banner surface and inline-runner snippet-fill guard.
 */
export interface JsonSnippet {
  readonly kind: 'json';
  /** Full vault-relative path including `.json` extension — identity (D-02) */
  path: string;
  name: string;
  template: string;
  placeholders: SnippetPlaceholder[];
  /** Phase 52 D-03: null on valid snippet; localized error string on legacy.
   *  Phase 84 (I18N-01): message language follows the translator passed to
   *  validatePlaceholders (defaults to English via defaultT). */
  validationError: string | null;
  /** @deprecated D-02: basename is source of truth; tolerated on disk only.
   *  Not `readonly` to preserve legacy snippet-manager-view write behavior
   *  until Phase 33 replaces that view. */
  id?: string;
}

/**
 * Phase 32 (D-01): Markdown snippet variant of the Snippet discriminated union.
 * A `.md` file under the snippet root is a first-class snippet whose raw file
 * contents are inserted as-is by the runner (Phase 35). No placeholder
 * substitution is performed for `MdSnippet`.
 */
export interface MdSnippet {
  readonly kind: 'md';
  /** Full vault-relative path including `.md` extension — identity */
  path: string;
  /** Basename without extension */
  name: string;
  /** Raw file contents */
  content: string;
}

/**
 * Phase 93 (EXTERNAL-LIB-01): Markdown template snippet — `.md` file with
 * YAML-like frontmatter containing metadata and placeholder definitions.
 * Supports placeholder substitution like JsonSnippet.
 */
export interface MdTemplateSnippet {
  readonly kind: 'md-template';
  /** Full vault-relative path including `.md` extension */
  path: string;
  name: string;
  /** Template body (without frontmatter) */
  template: string;
  placeholders: SnippetPlaceholder[];
  validationError: string | null;
  /** Optional metadata from frontmatter */
  id?: string;
  lang?: 'ru' | 'en';
  category?: string;
  description?: string;
  version?: number;
}

/**
 * Phase 32 (D-01): Discriminated union over snippet kinds. Callsites MUST
 * branch on `kind` to access variant-specific fields — mirrors the `RPNode`
 * pattern already established in `graph-model.ts`.
 */
export type Snippet = JsonSnippet | MdSnippet | MdTemplateSnippet;

/**
 * Phase 93 (EXTERNAL-LIB-01): renderSnippet-like interface for md-template
 * snippets. Same {{id}} -> value substitution engine as JsonSnippet.
 */
export function renderMdTemplateSnippet(
  snippet: MdTemplateSnippet,
  values: Record<string, string>,
): string {
  let output = snippet.template;
  for (const placeholder of snippet.placeholders) {
    const raw = values[placeholder.id] ?? '';
    output = output.split(`{{${placeholder.id}}}`).join(raw);
  }
  return output;
}

/**
 * Phase 32 (D-01, Claude's Discretion): backwards-compat alias for the
 * pre-phase-32 `SnippetFile` interface. Existing callsites that only deal
 * with JSON snippets can keep using `SnippetFile` without churn; new code
 * should prefer `JsonSnippet` or the `Snippet` union.
 */
export type SnippetFile = JsonSnippet;

/**
 * Phase 52 D-03: scan an untyped placeholder array for legacy types or
 * invalid choice configurations. Returns the first violation as a localized
 * error string, or null when all placeholders pass.
 *
 * Phase 84 (I18N-01): message text comes from the i18n locale configured by
 * the caller. The optional `t` translator defaults to English (defaultT).
 * Production callers (snippet-service) forward `plugin.i18n.t.bind(...)` to
 * keep messages aligned with the active UI locale.
 *
 * Input treated as `unknown` — no trust on shape (T-52-04).
 */
export function validatePlaceholders(
  placeholders: unknown,
  t: Translator = defaultT,
): string | null {
  if (!Array.isArray(placeholders)) return null;
  const legacyTypes = new Set(['number', 'multichoice', 'multi-choice']);
  for (const p of placeholders) {
    if (typeof p !== 'object' || p === null) continue;
    const ph = p as { type?: unknown; id?: unknown; options?: unknown };
    const id = typeof ph.id === 'string' ? ph.id : '<unknown>';
    const type = ph.type;
    if (typeof type === 'string' && legacyTypes.has(type)) {
      return t('snippetModel.legacyTypeError', { id, type });
    }
    if (type === 'choice' && (!Array.isArray(ph.options) || (ph.options as unknown[]).length === 0)) {
      return t('snippetModel.invalidChoiceError', { id });
    }
  }
  return null;
}

/**
 * Render a snippet template by substituting {{id}} tokens with values.
 * Phase 52 D-05/D-07: pure string-replace. Callers (SnippetFillInModal)
 * pre-join choice values using `placeholder.separator`. No unit suffix.
 * Uses split/join for compatibility with ES6 targets (RESEARCH.md Pitfall / key_research_finding 4).
 *
 * Phase 32: signature accepts `JsonSnippet` (was `SnippetFile`). Since
 * `SnippetFile = JsonSnippet`, existing JSON-only callers remain compatible.
 * `MdSnippet` is not renderable — callers must branch on `kind` first.
 * `MdTemplateSnippet` callers should use `renderMdTemplateSnippet`.
 */
export function renderSnippet(
  snippet: JsonSnippet,
  values: Record<string, string>,
): string {
  let output = snippet.template;
  for (const placeholder of snippet.placeholders) {
    const raw = values[placeholder.id] ?? '';
    // split/join replaces all occurrences without requiring replaceAll (ES2021+)
    output = output.split(`{{${placeholder.id}}}`).join(raw);
  }
  return output;
}

/**
 * Convert a human-readable label to a valid placeholder id slug (D-04).
 * "Patient age"    → "patient-age"
 * "Size (mm)"      → "size-mm"
 * Cyrillic input is preserved (e.g. "Patient age" Cyrillic → kebab-case Cyrillic).
 */
export function slugifyLabel(label: string): string {
  return label
    .toLowerCase()
    .trim()
    .replace(/[^\p{L}\p{N}]+/gu, '-')
    .replace(/^-+|-+$/g, '');
}

// snippets/snippet-service.ts
// Receives App and settings as constructor parameters — no direct Obsidian imports (NFR-01)
import type { App } from 'obsidian';
import type { RadiProtocolSettings } from '../settings';
import type { Snippet, JsonSnippet } from './snippet-model';
import { validatePlaceholders } from './snippet-model';
import { parseMarkdownTemplate, serializeMarkdownTemplate, hasMarkdownTemplateFrontmatter } from './md-template';
import { WriteMutex } from '../utils/write-mutex';
import { ensureFolderPath } from '../utils/vault-utils';
import { defaultT, type Translator } from '../i18n';

/**
 * Phase 34 (D-03): Build a canvas-ref mapping key from a vault-relative path.
 * - Strips `snippetRoot + '/'` prefix if present
 * - Strips trailing `.json` / `.md` (case-insensitive), once
 * - Returns '' when vaultPath === snippetRoot
 *
 * This is the single source of truth for converting between vault-relative
 * paths (what SnippetService deals in) and the snippet-root-relative,
 * extension-less format that `rewriteProtocolSnippetRefs` expects.
 */
export function toSnippetRelativePath(vaultPath: string, snippetRoot: string): string {
  if (vaultPath === snippetRoot) return '';
  const prefix = snippetRoot + '/';
  let rel = vaultPath.startsWith(prefix) ? vaultPath.slice(prefix.length) : vaultPath;
  rel = rel.replace(/\.(json|md)$/i, '');
  return rel;
}

/**
 * Full CRUD for snippet JSON files stored in {snippetFolderPath}/{id}.json (SNIP-01, D-14, D-15).
 * Every vault.modify() / vault.adapter.write() is wrapped in WriteMutex.runExclusive().
 * Folder existence is guaranteed via ensureFolderPath() before every write.
 */
export class SnippetService {
  private readonly app: App;
  private readonly settings: RadiProtocolSettings;
  private readonly mutex = new WriteMutex();
  /** Phase 84 (I18N-01): translator used for thrown error messages and
   *  validatePlaceholders forwarding. Defaults to English (defaultT) so the
   *  service can be constructed without a plugin reference in unit tests. */
  private readonly t: Translator;

  constructor(app: App, settings: RadiProtocolSettings, t: Translator = defaultT) {
    this.app = app;
    this.settings = settings;
    this.t = t;
  }

  /**
   * Phase 32 (D-10): Pre-I/O path-safety gate. Normalises and validates that
   * `path` is inside `this.settings.snippetFolderPath`. Returns the normalised
   * path on success, or null on rejection. Callers MUST return a safe
   * empty/null result when this returns null.
   */
  private assertInsideRoot(path: string): string | null {
    const root = this.settings.snippetFolderPath;
    const stripped = path.replace(/^\/+/, '');
    const rawSegments = stripped.split('/');
    const hasTraversal = rawSegments.some((s) => s === '..' || s === '.');
    const isAbsolute = path.startsWith('/');
    const normalized = rawSegments.filter((s) => s !== '').join('/');
    const insideRoot =
      !hasTraversal &&
      !isAbsolute &&
      (normalized === root || normalized.startsWith(root + '/'));
    if (!insideRoot) {
      console.error('[RadiProtocol] snippet-service rejected unsafe path:', path);
      return null;
    }
    return normalized;
  }

  /**
   * Phase 32: basename of a vault-relative path with its extension stripped.
   * Used to derive snippet `name` when loading/listing.
   */
  private basenameNoExt(path: string): string {
    const base = path.slice(path.lastIndexOf('/') + 1);
    const dot = base.lastIndexOf('.');
    return dot > 0 ? base.slice(0, dot) : base;
  }

  /**
   * List direct children of a folder within the snippet root.
   * Phase 30 D-18..D-21. Used by the runner picker.
   *
   * @param folderPath Full vault-relative path (D-19). Caller composes
   *   `${settings.snippetFolderPath}/${node.subfolderPath}` when subfolderPath is set.
   * @returns Direct-children folders (basenames, sorted) and parsed SnippetFile objects (sorted by name).
   *   Missing folder → empty. Corrupt JSON → skipped silently.
   *   Path outside snippet root → silently rejected (T-30-01).
   */
  async listFolder(
    folderPath: string,
  ): Promise<{ folders: string[]; snippets: Snippet[] }> {
    // Phase 32 (D-10): path-safety gate via assertInsideRoot helper.
    const normalized = this.assertInsideRoot(folderPath);
    if (normalized === null) return { folders: [], snippets: [] };

    const exists = await this.app.vault.adapter.exists(normalized);
    if (!exists) return { folders: [], snippets: [] };

    let listing: { files: string[]; folders: string[] };
    try {
      listing = await this.app.vault.adapter.list(normalized);
    } catch {
      return { folders: [], snippets: [] };
    }

    // Folder basenames (strip `${normalized}/` prefix). Only direct children.
    const folders: string[] = [];
    for (const f of listing.folders) {
      const rel = f.slice(normalized.length + 1);
      if (rel !== '' && !rel.includes('/')) folders.push(rel);
    }
    folders.sort((a, b) => a.localeCompare(b));

    // Phase 32 (D-01, D-02): parse .json as JsonSnippet, read .md as MdSnippet.
    // basename is authoritative for `name` (D-02); corrupt files skipped silently.
    const snippets: Snippet[] = [];
    for (const filePath of listing.files) {
      const basename = this.basenameNoExt(filePath);
      if (filePath.endsWith('.json')) {
        try {
          const raw = await this.app.vault.adapter.read(filePath);
          const parsed = JSON.parse(raw) as Partial<JsonSnippet>;
          // Phase 52 D-03: hard-validation — surface legacy placeholder types
          // and empty-choice options as validationError so Editor/Runner can
          // block rendering. Syntax-broken JSON still silently skipped via catch.
          const validationError = validatePlaceholders(parsed.placeholders, this.t);
          snippets.push({
            kind: 'json',
            path: filePath,
            name: basename,
            template: parsed.template ?? '',
            placeholders: (parsed.placeholders ?? []) as JsonSnippet['placeholders'],
            validationError,
          });
        } catch {
          // Corrupt file — skip silently (D-03 explicit: syntax-broken JSON stays silent-skip).
        }
      } else if (filePath.endsWith('.md')) {
        try {
          const raw = await this.app.vault.adapter.read(filePath);
          if (hasMarkdownTemplateFrontmatter(raw)) {
            snippets.push(parseMarkdownTemplate(filePath, raw, basename, this.t));
          } else {
            snippets.push({
              kind: 'md',
              path: filePath,
              name: basename,
              content: raw,
            });
          }
        } catch {
          // Unreadable — skip silently.
        }
      }
      // Other extensions: skip.
    }
    snippets.sort((a, b) => a.name.localeCompare(b.name));

    return { folders, snippets };
  }

  /**
   * Phase 32 (D-03): Load a snippet by full vault-relative path.
   * Routes by extension: `.json` → JsonSnippet, `.md` → MdSnippet.
   * Returns null if path is unsafe, file missing, or JSON corrupt.
   */
  async load(path: string): Promise<Snippet | null> {
    const normalized = this.assertInsideRoot(path);
    if (normalized === null) return null;
    const exists = await this.app.vault.adapter.exists(normalized);
    if (!exists) return null;
    try {
      const raw = await this.app.vault.adapter.read(normalized);
      const basename = this.basenameNoExt(normalized);
      if (normalized.endsWith('.json')) {
        const parsed = JSON.parse(raw) as Partial<JsonSnippet>;
        // Phase 52 D-03: populate validationError on every JsonSnippet return.
        const validationError = validatePlaceholders(parsed.placeholders, this.t);
        return {
          kind: 'json',
          path: normalized,
          name: basename,
          template: parsed.template ?? '',
          placeholders: (parsed.placeholders ?? []) as JsonSnippet['placeholders'],
          validationError,
        };
      }
      if (normalized.endsWith('.md')) {
        if (hasMarkdownTemplateFrontmatter(raw)) {
          return parseMarkdownTemplate(normalized, raw, basename, this.t);
        }
        return { kind: 'md', path: normalized, name: basename, content: raw };
      }
      return null;
    } catch {
      return null;
    }
  }

  /**
   * Phase 32 (D-03): Save a snippet. Branches on `kind`:
   *   - `json` → sanitize + JSON.stringify
   *   - `md`   → write raw content (free-text, no sanitisation)
   * Wraps write in WriteMutex per-path (D-11). Ensures parent folder exists.
   * Throws on unsafe path (D-10).
   */
  async save(snippet: Snippet): Promise<void> {
    const normalized = this.assertInsideRoot(snippet.path);
    if (normalized === null) {
      throw new Error(`[RadiProtocol] save rejected unsafe path: ${snippet.path}`);
    }
    await this.mutex.runExclusive(normalized, async () => {
      await ensureFolderPath(this.app.vault, this.settings.snippetFolderPath);
      const lastSlash = normalized.lastIndexOf('/');
      const parent = lastSlash > 0 ? normalized.slice(0, lastSlash) : '';
      if (parent !== '' && parent !== this.settings.snippetFolderPath) {
        await ensureFolderPath(this.app.vault, parent);
      }
      let payload: string;
      if (snippet.kind === 'json') {
        const clean = this.sanitizeJson(snippet);
        payload = JSON.stringify(clean, null, 2);
      } else if (snippet.kind === 'md-template') {
        payload = serializeMarkdownTemplate(snippet);
      } else {
        // md: raw free-text content, no sanitisation (D-01)
        const mdSnippet = snippet as Extract<Snippet, { kind: 'md' }>;
        payload = mdSnippet.content;
      }
      const exists = await this.app.vault.adapter.exists(normalized);
      if (exists) {
        await this.app.vault.adapter.write(normalized, payload);
      } else {
        await this.app.vault.create(normalized, payload);
      }
    });
  }

  /**
   * Phase 32 (D-03, D-08, D-11): Delete a snippet file by path.
   * Uses `fileManager.trashFile(file)` so Obsidian respects the user's
   * configured deletion preference. No-op on unsafe path or missing file.
   * Wrapped in WriteMutex per-path.
   */
  async delete(path: string): Promise<void> {
    const normalized = this.assertInsideRoot(path);
    if (normalized === null) return;
    await this.mutex.runExclusive(normalized, async () => {
      const file = this.app.vault.getAbstractFileByPath(normalized);
      if (file === null) return;
      // D-08: route deletion through Obsidian FileManager user preference.
      await this.app.fileManager.trashFile(file);
    });
  }

  /**
   * Phase 32 (D-03): Check if a snippet file exists at the given path.
   * Returns false on unsafe path.
   */
  async exists(path: string): Promise<boolean> {
    const normalized = this.assertInsideRoot(path);
    if (normalized === null) return false;
    return this.app.vault.adapter.exists(normalized);
  }

  /**
   * Phase 33 (D-17): Create an empty folder inside the snippet root.
   * Path-safety gated via assertInsideRoot; rejects unsafe path by throwing.
   * Idempotent — ensureFolderPath is a no-op when the folder already exists.
   * Wrapped in WriteMutex per normalized path.
   */
  async createFolder(path: string): Promise<void> {
    const normalized = this.assertInsideRoot(path);
    if (normalized === null) {
      throw new Error(`[RadiProtocol] createFolder rejected unsafe path: ${path}`);
    }
    await this.mutex.runExclusive(normalized, async () => {
      await ensureFolderPath(this.app.vault, normalized);
    });
  }

  /**
   * Phase 33 (D-16, D-17): Trash a folder recursively via FileManager.
   * Path-safety gated; unsafe path or missing folder → silent no-op (no throw).
   * Per D-17 refined: does NOT call rewriteProtocolSnippetRefs — deletes leave canvas refs broken.
   * Wrapped in WriteMutex per normalized path.
   */
  async deleteFolder(path: string): Promise<void> {
    const normalized = this.assertInsideRoot(path);
    if (normalized === null) return;
    await this.mutex.runExclusive(normalized, async () => {
      const folder = this.app.vault.getAbstractFileByPath(normalized);
      if (folder === null) return;
      // D-08: route deletion through Obsidian FileManager user preference.
      await this.app.fileManager.trashFile(folder);
    });
  }

  /**
   * Phase 33 (D-15): Recursively walk a folder and return every descendant
   * file + subfolder (vault-relative paths as adapter.list returns them).
   * Used by the folder-delete confirm dialog to display the exact count of
   * items that will be trashed.
   * Unsafe path → { files: [], folders: [], total: 0 }.
   */
  async listFolderDescendants(
    path: string,
  ): Promise<{ files: string[]; folders: string[]; total: number }> {
    const normalized = this.assertInsideRoot(path);
    if (normalized === null) return { files: [], folders: [], total: 0 };
    const files: string[] = [];
    const folders: string[] = [];
    const queue: string[] = [normalized];
    while (queue.length > 0) {
      const current = queue.shift() as string;
      let listing: { files: string[]; folders: string[] };
      try {
        listing = await this.app.vault.adapter.list(current);
      } catch {
        continue;
      }
      for (const f of listing.files) files.push(f);
      for (const sub of listing.folders) {
        folders.push(sub);
        queue.push(sub);
      }
    }
    return { files, folders, total: files.length + folders.length };
  }

  async duplicateSnippet(path: string): Promise<string> {
    const original = await this.load(path);
    if (original === null) throw new Error(this.t('snippetService.fileNotFound', { path }));

    const dot = path.lastIndexOf('.');
    const base = dot >= 0 ? path.slice(0, dot) : path;
    const ext = dot >= 0 ? path.slice(dot) : '';
    let candidate = `${base}-copy${ext}`;
    let index = 2;
    while (await this.exists(candidate)) {
      candidate = `${base}-copy-${index}${ext}`;
      index += 1;
    }

    const duplicate = original.kind === 'json'
      ? { ...original, path: candidate, name: this.basenameNoExt(candidate), placeholders: original.placeholders.map((p) => ({ ...p })) }
      : { ...original, path: candidate, name: this.basenameNoExt(candidate) };
    await this.save(duplicate);
    return candidate;
  }

  /**
   * Phase 34 (MOVE-01, RENAME-03): Rename a snippet file in place (same folder).
   * Preserves the original extension (.json or .md). Rejects basenames that
   * contain slashes or are empty/whitespace-only. Collision-checks destination
   * before touching the source. Wrapped in WriteMutex per normalized source.
   * Returns the new normalized path. No-op (returns unchanged path) when the
   * normalized old and new paths are identical.
   */
  async renameSnippet(oldPath: string, newBasename: string): Promise<string> {
    const normalizedOld = this.assertInsideRoot(oldPath);
    if (normalizedOld === null) {
      throw new Error(`[RadiProtocol] renameSnippet rejected unsafe path: ${oldPath}`);
    }
    if (/[\\/]/.test(newBasename) || newBasename.trim() === '') {
      throw new Error(this.t('snippetService.invalidName'));
    }
    const lastSlash = normalizedOld.lastIndexOf('/');
    const parent = lastSlash > 0 ? normalizedOld.slice(0, lastSlash) : '';
    const lower = normalizedOld.toLowerCase();
    const ext = lower.endsWith('.md') ? '.md' : '.json';
    const newPath = parent === '' ? `${newBasename}${ext}` : `${parent}/${newBasename}${ext}`;
    const normalizedNew = this.assertInsideRoot(newPath);
    if (normalizedNew === null) {
      throw new Error(`[RadiProtocol] renameSnippet rejected unsafe new path: ${newPath}`);
    }
    if (normalizedOld === normalizedNew) return normalizedNew;
    if (await this.app.vault.adapter.exists(normalizedNew)) {
      throw new Error(this.t('snippetService.pathExists', { path: normalizedNew }));
    }
    await this.mutex.runExclusive(normalizedOld, async () => {
      const file = this.app.vault.getAbstractFileByPath(normalizedOld);
      if (file === null) throw new Error(this.t('snippetService.fileNotFound', { path: normalizedOld }));
      await this.app.vault.rename(file, normalizedNew);
    });
    return normalizedNew;
  }

  /**
   * Phase 34 (MOVE-01): Move a snippet file into another folder under the
   * snippet root, preserving its basename + extension. Ensures the destination
   * folder exists before the rename. Collision-checks destination.
   */
  async moveSnippet(oldPath: string, newFolder: string): Promise<string> {
    const normalizedOld = this.assertInsideRoot(oldPath);
    if (normalizedOld === null) {
      throw new Error(`[RadiProtocol] moveSnippet rejected unsafe path: ${oldPath}`);
    }
    const normalizedFolder = this.assertInsideRoot(newFolder);
    if (normalizedFolder === null) {
      throw new Error(`[RadiProtocol] moveSnippet rejected unsafe destination: ${newFolder}`);
    }
    const basename = normalizedOld.slice(normalizedOld.lastIndexOf('/') + 1);
    const normalizedNew =
      normalizedFolder === '' ? basename : `${normalizedFolder}/${basename}`;
    if (normalizedOld === normalizedNew) return normalizedNew;
    if (await this.app.vault.adapter.exists(normalizedNew)) {
      throw new Error(this.t('snippetService.pathExists', { path: normalizedNew }));
    }
    await this.mutex.runExclusive(normalizedOld, async () => {
      await ensureFolderPath(this.app.vault, normalizedFolder);
      const file = this.app.vault.getAbstractFileByPath(normalizedOld);
      if (file === null) throw new Error(this.t('snippetService.fileNotFound', { path: normalizedOld }));
      await this.app.vault.rename(file, normalizedNew);
    });
    return normalizedNew;
  }

  /**
   * Phase 34 (RENAME-03): Rename a folder in place (within the same parent).
   * Rejects basenames with slashes. Collision-checks destination.
   */
  async renameFolder(oldPath: string, newBasename: string): Promise<string> {
    const normalizedOld = this.assertInsideRoot(oldPath);
    if (normalizedOld === null) {
      throw new Error(`[RadiProtocol] renameFolder rejected unsafe path: ${oldPath}`);
    }
    if (/[\\/]/.test(newBasename) || newBasename.trim() === '') {
      throw new Error(this.t('snippetService.invalidName'));
    }
    const lastSlash = normalizedOld.lastIndexOf('/');
    const parent = lastSlash > 0 ? normalizedOld.slice(0, lastSlash) : '';
    const newPath = parent === '' ? newBasename : `${parent}/${newBasename}`;
    const normalizedNew = this.assertInsideRoot(newPath);
    if (normalizedNew === null) {
      throw new Error(`[RadiProtocol] renameFolder rejected unsafe new path: ${newPath}`);
    }
    if (normalizedOld === normalizedNew) return normalizedNew;
    // Self-descendant guard: renaming into own subtree is nonsensical but
    // guard defensively (e.g. parent == '' edge cases).
    if (
      normalizedNew === normalizedOld ||
      normalizedNew.startsWith(normalizedOld + '/')
    ) {
      throw new Error(this.t('snippetService.cannotMoveIntoSelf'));
    }
    if (await this.app.vault.adapter.exists(normalizedNew)) {
      throw new Error(this.t('snippetService.pathExists', { path: normalizedNew }));
    }
    await this.mutex.runExclusive(normalizedOld, async () => {
      const folder = this.app.vault.getAbstractFileByPath(normalizedOld);
      if (folder === null) throw new Error(this.t('snippetService.folderNotFound', { path: normalizedOld }));
      await this.app.vault.rename(folder, normalizedNew);
    });
    return normalizedNew;
  }

  /**
   * Phase 34 (MOVE-02): Move a folder into another parent folder under the
   * snippet root. Guards against moving a folder into itself or into any of
   * its descendants. Ensures the new parent exists. Collision-checks destination.
   */
  async moveFolder(oldPath: string, newParent: string): Promise<string> {
    const normalizedOld = this.assertInsideRoot(oldPath);
    if (normalizedOld === null) {
      throw new Error(`[RadiProtocol] moveFolder rejected unsafe path: ${oldPath}`);
    }
    const normalizedParent = this.assertInsideRoot(newParent);
    if (normalizedParent === null) {
      throw new Error(`[RadiProtocol] moveFolder rejected unsafe destination: ${newParent}`);
    }
    const basename = normalizedOld.slice(normalizedOld.lastIndexOf('/') + 1);
    const normalizedNew =
      normalizedParent === '' ? basename : `${normalizedParent}/${basename}`;
    // Self-descendant guard: reject move onto self OR into any descendant.
    // Also reject when the target parent IS the source or inside the source
    // subtree, since the resulting path would be nested under itself.
    if (
      normalizedParent === normalizedOld ||
      normalizedParent.startsWith(normalizedOld + '/') ||
      normalizedNew === normalizedOld ||
      normalizedNew.startsWith(normalizedOld + '/')
    ) {
      throw new Error(this.t('snippetService.cannotMoveIntoSelf'));
    }
    if (await this.app.vault.adapter.exists(normalizedNew)) {
      throw new Error(this.t('snippetService.pathExists', { path: normalizedNew }));
    }
    await this.mutex.runExclusive(normalizedOld, async () => {
      await ensureFolderPath(this.app.vault, normalizedParent);
      const folder = this.app.vault.getAbstractFileByPath(normalizedOld);
      if (folder === null) throw new Error(this.t('snippetService.folderNotFound', { path: normalizedOld }));
      await this.app.vault.rename(folder, normalizedNew);
    });
    return normalizedNew;
  }

  /**
   * Phase 34 (D-06): Return the sorted list of every folder under the snippet
   * root, including the root itself. Used by SnippetEditorModal's folder field
   * and SnippetTreePicker. Delegates to listFolderDescendants.
   */
  async listAllFolders(): Promise<string[]> {
    const root = this.settings.snippetFolderPath;
    const { folders } = await this.listFolderDescendants(root);
    const set = new Set<string>([root, ...folders]);
    return Array.from(set).sort((a, b) => a.localeCompare(b));
  }

  /**
   * Phase 32: Strip control characters (U+0000–U+001F, U+007F) from all
   * string values in a JsonSnippet and produce a plain disk payload object
   * (without runtime-only `kind` / `path` / deprecated `id`). Preserves
   * ASVS V5 input sanitization (T-5-01).
   */
  private sanitizeJson(snippet: JsonSnippet): {
    name: string;
    template: string;
    placeholders: JsonSnippet['placeholders'];
  } {
    // eslint-disable-next-line no-control-regex
    const clean = (s: string): string => s.replace(new RegExp('[\\x00-\\x1f\\x7f]', 'g'), '');
    return {
      name: clean(snippet.name),
      template: clean(snippet.template),
      placeholders: snippet.placeholders.map((p) => ({
        ...p,
        label: clean(p.label),
        options: p.options?.map(clean),
        // Phase 52 D-02: legacy join-field renamed to `separator`; D-07: legacy unit field removed.
        separator: p.separator !== undefined ? clean(p.separator) : undefined,
      })),
    };
  }
}

// src/protocol/protocol-document.ts
// Storage-neutral protocol document model for RadiProtocol.
// This is the canonical on-disk shape for .rp.json protocol files.
//
// Design goals:
// - Decouple from Obsidian Canvas internals (no .canvas dependency).
// - Keep fields diffable and human-readable.
// - Support schema evolution via version field.
// - Map cleanly to runtime ProtocolGraph without loss.

import type { RPNodeKind } from '../graph/graph-model';

/** Canonical schema identifier for RadiProtocol JSON files. */
export const PROTOCOL_SCHEMA = 'radiprotocol.protocol' as const;

/** Current on-disk schema version. Bump on breaking changes. */
export const PROTOCOL_VERSION = 1 as const;

/**
 * Canonical on-disk shape for a RadiProtocol protocol (.rp.json).
 * Versioned to allow future evolution without breaking existing files.
 */
export interface ProtocolDocumentV1 {
  /** Fixed schema identifier: 'radiprotocol.protocol' */
  schema: typeof PROTOCOL_SCHEMA;
  /** Schema version number. Current: 1 */
  version: typeof PROTOCOL_VERSION;
  /** Unique document ID (UUID or similar). */
  id: string;
  /** Human-readable protocol title. */
  title: string;
  /** ISO 8601 timestamp of creation. */
  createdAt: string;
  /** ISO 8601 timestamp of last update. */
  updatedAt: string;
  /** All protocol nodes. Order is not semantically significant. */
  nodes: ProtocolNodeRecord[];
  /** All protocol edges. Order is not semantically significant. */
  edges: ProtocolEdgeRecord[];
  /** Whether final runner self-check checklist is enabled. */
  selfCheckEnabled?: boolean;
  /** Optional final runner self-check checklist items. */
  selfCheckItems?: string[];
  /** Optional viewport state for visual editor persistence. */
  viewport?: {
    x: number;
    y: number;
    zoom: number;
  };
  /** Optional preferred editor auto-layout direction. */
  layoutDirection?: 'LR' | 'TB';
}

/**
 * On-disk node record. Maps to runtime RPNode after parsing.
 *
 * Design notes:
 * - `kind` may be null for untyped nodes during authoring.
 * - `fields` is a flat key-value map; parser normalizes to typed RPNode shape.
 * - Legacy `radiprotocol_*` prefix is NOT used in new .rp.json files.
 *   Keys in `fields` use camelCase without prefix (e.g. 'questionText').
 */
export interface ProtocolNodeRecord {
  /** Unique node ID within the document. */
  id: string;
  /** Node kind. Null means untyped/plain node (authoring intermediate state). */
  kind: RPNodeKind | null;
  /** X coordinate in visual editor space (pixels). */
  x: number;
  /** Y coordinate in visual editor space (pixels). */
  y: number;
  /** Node width in pixels. */
  width: number;
  /** Node height in pixels. */
  height: number;
  /** Optional node background color (CSS color string). */
  color?: string;
  /** Optional raw text content (fallback for label/body). */
  text?: string;
  /**
   * Typed node fields. Keys are camelCase without prefix:
   * - questionText, answerText, displayLabel, content, separator,
   *   headerText, subfolderPath, snippetLabel, snippetSeparator, snippetPath.
   *
   * Parser validates field presence/absence per node kind.
   */
  fields: Record<string, unknown>;
}

/**
 * On-disk edge record. Maps directly to runtime RPEdge.
 */
export interface ProtocolEdgeRecord {
  /** Unique edge ID within the document. */
  id: string;
  /** Source node ID. Must reference an existing node. */
  fromNodeId: string;
  /** Target node ID. Must reference an existing node. */
  toNodeId: string;
  /** Optional edge label (shown on connector in visual editor and runner). */
  label?: string;
}

/**
 * Utility: generate a new ProtocolDocumentV1 with minimal valid structure.
 * Used by ProtocolDocumentStore.create() and tests.
 */
export function createEmptyProtocolDocument(
  id: string,
  title: string,
  now = new Date()
): ProtocolDocumentV1 {
  const iso = now.toISOString();
  return {
    schema: PROTOCOL_SCHEMA,
    version: PROTOCOL_VERSION,
    id,
    title,
    createdAt: iso,
    updatedAt: iso,
    nodes: [],
    edges: [],
    layoutDirection: 'LR',
  };
}

/**
 * Utility: check if a value looks like a ProtocolDocumentV1.
 * Does NOT validate field semantics — only schema/version shape.
 */
export function isProtocolDocumentV1(value: unknown): value is ProtocolDocumentV1 {
  if (typeof value !== 'object' || value === null) return false;
  const doc = value as Record<string, unknown>;
  return (
    doc['schema'] === PROTOCOL_SCHEMA &&
    doc['version'] === PROTOCOL_VERSION &&
    typeof doc['id'] === 'string' &&
    typeof doc['title'] === 'string' &&
    typeof doc['createdAt'] === 'string' &&
    typeof doc['updatedAt'] === 'string' &&
    Array.isArray(doc['nodes']) &&
    Array.isArray(doc['edges'])
  );
}

import { ItemView, Notice, TFile, WorkspaceLeaf, setIcon } from 'obsidian';
import type RadiProtocolPlugin from '../main';
import type { ProtocolDocumentV1, ProtocolEdgeRecord, ProtocolNodeRecord } from '../protocol/protocol-document';
import type { RPNodeKind } from '../graph/graph-model';
import { SnippetTreePicker, type SnippetTreePickerResult } from './snippet-tree-picker';
import { defaultT, type Translator } from '../i18n';
import dagre from 'dagre';

export const PROTOCOL_EDITOR_VIEW_TYPE = 'radiprotocol-protocol-editor';

/** Throw a consistent error when the protocol file is no longer in the vault. */
export function protocolMissingFileError(): never {
	throw new Error('Protocol file disappeared');
}

/* Phase 4D — default node dimensions and kind-specific defaults */
const DEFAULT_NODE_WIDTH = 200;
const DEFAULT_NODE_HEIGHT = 80;
const DEFAULT_VIEWPORT_WIDTH = 30000;
const DEFAULT_VIEWPORT_HEIGHT = 24000;
const PROTOCOL_EDITOR_ORIGIN_X = DEFAULT_VIEWPORT_WIDTH / 2;
const PROTOCOL_EDITOR_ORIGIN_Y = DEFAULT_VIEWPORT_HEIGHT / 2;
const MIN_NODE_WIDTH = 120;
const MIN_NODE_HEIGHT = 50;
const MIN_ZOOM = 0.1;
const MAX_ZOOM = 2;
const ZOOM_STEP = 0.1;

interface NodeKindDefault {
  kind: RPNodeKind | null;
  fields: Record<string, unknown>;
  text?: string;
  color?: string;
}

type ProtocolEditorLayoutDirection = 'LR' | 'TB';

type ProtocolEditorPortSide = 'left' | 'right' | 'top' | 'bottom';

interface ConnectionDragState {
  fromNodeId: string;
  startX: number;
  startY: number;
  previewPath: SVGPathElement;
}

interface ProtocolEditorEdgeRoute {
  d: string;
  labelX: number;
  labelY: number;
}

interface ProtocolEditorEdgePoint {
  x: number;
  y: number;
}

const EDGE_ROUTE_EPSILON = 0.5;

function roundProtocolEditorEdgeCoord(value: number): number {
  return Math.round(value * 100) / 100;
}

function formatProtocolEditorEdgeCoord(value: number): string {
  return String(roundProtocolEditorEdgeCoord(value));
}

function sameProtocolEditorEdgePoint(a: ProtocolEditorEdgePoint, b: ProtocolEditorEdgePoint): boolean {
  return Math.hypot(a.x - b.x, a.y - b.y) < EDGE_ROUTE_EPSILON;
}

function normalizeProtocolEditorEdgePoints(points: ProtocolEditorEdgePoint[]): ProtocolEditorEdgePoint[] {
  const normalized: ProtocolEditorEdgePoint[] = [];
  for (const point of points) {
    const rounded = { x: roundProtocolEditorEdgeCoord(point.x), y: roundProtocolEditorEdgeCoord(point.y) };
    const previous = normalized[normalized.length - 1];
    if (previous !== undefined && sameProtocolEditorEdgePoint(previous, rounded)) continue;
    normalized.push(rounded);
  }
  return normalized;
}

function protocolEditorLineCommand(point: ProtocolEditorEdgePoint): string {
  return `L ${formatProtocolEditorEdgeCoord(point.x)} ${formatProtocolEditorEdgeCoord(point.y)}`;
}

function roundedProtocolEditorOrthogonalPath(points: ProtocolEditorEdgePoint[], maxBend: number): string {
  const normalized = normalizeProtocolEditorEdgePoints(points);
  if (normalized.length === 0) return '';
  if (normalized.length === 1) return `M ${formatProtocolEditorEdgeCoord(normalized[0]!.x)} ${formatProtocolEditorEdgeCoord(normalized[0]!.y)}`;

  const commands = [`M ${formatProtocolEditorEdgeCoord(normalized[0]!.x)} ${formatProtocolEditorEdgeCoord(normalized[0]!.y)}`];
  for (let index = 1; index < normalized.length; index += 1) {
    const current = normalized[index]!;
    const next = normalized[index + 1];
    if (next === undefined || maxBend <= EDGE_ROUTE_EPSILON) {
      commands.push(protocolEditorLineCommand(current));
      continue;
    }

    const previous = normalized[index - 1]!;
    const inLength = Math.hypot(current.x - previous.x, current.y - previous.y);
    const outLength = Math.hypot(next.x - current.x, next.y - current.y);
    const bend = Math.min(maxBend, inLength / 2, outLength / 2);
    if (bend <= EDGE_ROUTE_EPSILON) {
      commands.push(protocolEditorLineCommand(current));
      continue;
    }

    const inUnit = { x: (current.x - previous.x) / inLength, y: (current.y - previous.y) / inLength };
    const outUnit = { x: (next.x - current.x) / outLength, y: (next.y - current.y) / outLength };
    const bendStart = { x: current.x - inUnit.x * bend, y: current.y - inUnit.y * bend };
    const bendEnd = { x: current.x + outUnit.x * bend, y: current.y + outUnit.y * bend };

    commands.push(protocolEditorLineCommand(bendStart));
    commands.push(`Q ${formatProtocolEditorEdgeCoord(current.x)} ${formatProtocolEditorEdgeCoord(current.y)} ${formatProtocolEditorEdgeCoord(bendEnd.x)} ${formatProtocolEditorEdgeCoord(bendEnd.y)}`);
  }

  return commands.join(' ');
}

interface ProtocolEditorPortAnchor {
  x: number;
  y: number;
  side: ProtocolEditorPortSide;
}

interface ProtocolEditorNodeMeasurement {
  width: number;
  height: number;
}

interface ProtocolEditorMeasuredNodeGeometry extends ProtocolEditorNodeMeasurement {
  x: number;
  y: number;
}

interface ProtocolEditorLiveNodeGeometry extends ProtocolEditorMeasuredNodeGeometry {
  id: string;
}

interface ProtocolEditorLayoutOptions {
  direction: ProtocolEditorLayoutDirection;
  nodesep: number;
  ranksep: number;
  edgesep: number;
}

interface ProtocolEditorCreateNodeOptions {
  onEditModalOpened?: () => void;
  onCreateAbandoned?: () => void;
  onCreateFailed?: () => void;
}

const PROTOCOL_EDITOR_LAYOUT_CONFIG: Record<ProtocolEditorLayoutDirection, ProtocolEditorLayoutOptions> = {
  LR: {
    direction: 'LR',
    nodesep: 96,
    ranksep: 152,
    edgesep: 32,
  },
  TB: {
    direction: 'TB',
    nodesep: 112,
    ranksep: 144,
    edgesep: 36,
  },
};

function protocolEditorInputPortSide(direction: ProtocolEditorLayoutDirection): ProtocolEditorPortSide {
  return direction === 'TB' ? 'top' : 'left';
}

function protocolEditorOutputPortSide(direction: ProtocolEditorLayoutDirection): ProtocolEditorPortSide {
  return direction === 'TB' ? 'bottom' : 'right';
}

function protocolEditorPortAnchor(node: Pick<ProtocolNodeRecord, 'x' | 'y' | 'width' | 'height'>, side: ProtocolEditorPortSide): ProtocolEditorPortAnchor {
  switch (side) {
    case 'left':
      return { x: node.x, y: node.y + node.height / 2, side };
    case 'right':
      return { x: node.x + node.width, y: node.y + node.height / 2, side };
    case 'top':
      return { x: node.x + node.width / 2, y: node.y, side };
    case 'bottom':
      return { x: node.x + node.width / 2, y: node.y + node.height, side };
  }
}

function protocolEditorNodeMeasurement(node: Pick<ProtocolNodeRecord, 'width' | 'height'>): ProtocolEditorNodeMeasurement {
  return {
    width: Math.max(MIN_NODE_WIDTH, Math.round(node.width || DEFAULT_NODE_WIDTH)),
    height: Math.max(MIN_NODE_HEIGHT, Math.round(node.height || DEFAULT_NODE_HEIGHT)),
  };
}

function protocolEditorNormalizeNodeMeasurement(width: number, height: number): ProtocolEditorNodeMeasurement {
  return {
    width: Math.max(MIN_NODE_WIDTH, Math.round(width || DEFAULT_NODE_WIDTH)),
    height: Math.max(MIN_NODE_HEIGHT, Math.round(height || DEFAULT_NODE_HEIGHT)),
  };
}

function protocolEditorMeasuredNodeAnchor(
  nodeEl: HTMLElement,
  side: ProtocolEditorPortSide,
): ProtocolEditorPortAnchor {
  const left = parseFloat(nodeEl.style.left || '0');
  const top = parseFloat(nodeEl.style.top || '0');
  const width = Math.max(MIN_NODE_WIDTH, nodeEl.offsetWidth);
  const height = Math.max(MIN_NODE_HEIGHT, nodeEl.offsetHeight);
  return protocolEditorPortAnchor({
    x: left - PROTOCOL_EDITOR_ORIGIN_X,
    y: top - PROTOCOL_EDITOR_ORIGIN_Y,
    width,
    height,
  }, side);
}

function protocolEditorAnchorToSurfacePoint(anchor: ProtocolEditorPortAnchor): { x: number; y: number } {
  return {
    x: worldXToSurfaceX(anchor.x),
    y: worldYToSurfaceY(anchor.y),
  };
}

function protocolEditorLayoutDirectionFromDocument(doc: ProtocolDocumentV1 | null | undefined): ProtocolEditorLayoutDirection {
  return doc?.layoutDirection === 'TB' ? 'TB' : 'LR';
}

interface PanState {
  startClientX: number;
  startClientY: number;
  startScrollLeft: number;
  startScrollTop: number;
}

function worldXToSurfaceX(x: number): number {
  return x + PROTOCOL_EDITOR_ORIGIN_X;
}

function worldYToSurfaceY(y: number): number {
  return y + PROTOCOL_EDITOR_ORIGIN_Y;
}

const NODE_KIND_DEFAULTS: Record<string, NodeKindDefault> = {
  start: { kind: 'start', fields: {}, color: 'rgba(76, 175, 80, 0.28)' },
  question: { kind: 'question', fields: { questionText: '' }, color: 'rgba(33, 150, 243, 0.24)' },
  answer: { kind: 'answer', fields: { answerText: '' }, color: 'rgba(255, 193, 7, 0.28)' },
  'text-block': { kind: 'text-block', fields: { content: '' }, color: 'rgba(255, 235, 59, 0.24)' },
  loop: { kind: 'loop', fields: { headerText: '' }, color: 'rgba(233, 30, 99, 0.24)' },
  snippet: { kind: 'snippet', fields: {}, color: 'rgba(156, 39, 176, 0.24)' },
};

const EDITABLE_NODE_KINDS: RPNodeKind[] = ['start', 'question', 'answer', 'text-block', 'loop', 'snippet'];

/** CSS/attribute token for a node kind — always raw "untyped", never i18n. */
export function nodeKindToken(kind: RPNodeKind | null): string {
  return kind ?? 'untyped';
}

export function defaultColorForProtocolEditorNodeKind(kind: RPNodeKind | null): string | undefined {
  if (kind === null) return undefined;
  return NODE_KIND_DEFAULTS[kind]?.color;
}

export function fieldsForProtocolEditorNodeKind(kind: RPNodeKind | null): Record<string, unknown> {
  if (kind === null) return {};
  return { ...(NODE_KIND_DEFAULTS[kind]?.fields ?? {}) };
}

export function normalizeProtocolEditorEdgeLabel(label: string, isLoopExit: boolean): string | undefined {
  const withoutPrefix = label.trim().replace(/^\+\s*/, '').trim();
  if (isLoopExit && withoutPrefix !== '') return `+${withoutPrefix}`;
  return withoutPrefix === '' ? undefined : withoutPrefix;
}

export function displayProtocolEditorEdgeLabel(label: string | undefined): string {
  return (label ?? '').trim().replace(/^\+\s*/, '').trim();
}

export function isProtocolEditorLoopExitLabel(label: string | undefined): boolean {
  return (label ?? '').trim().startsWith('+');
}

export function nodeTitle(node: ProtocolNodeRecord, t: Translator = defaultT): string {
  if (typeof node.text === 'string' && node.text.trim() !== '') return node.text.trim();
  if (typeof node.fields['displayLabel'] === 'string') return node.fields['displayLabel'];
  if (typeof node.fields['questionText'] === 'string') return node.fields['questionText'];
  if (typeof node.fields['answerText'] === 'string') return node.fields['answerText'];
  if (typeof node.fields['content'] === 'string') return node.fields['content'];
  return node.kind ?? t('protocolEditor.untyped');
}

export function defaultProtocolEditorEdgeLabelForTarget(node: ProtocolNodeRecord | undefined): string | undefined {
  if (node === undefined) return undefined;
  const candidates = node.kind === 'answer'
    ? [node.fields['displayLabel'], node.fields['answerText'], node.text]
    : node.kind === 'snippet'
      ? [node.fields['snippetLabel'], node.text]
      : [];
  for (const candidate of candidates) {
    if (typeof candidate === 'string' && candidate.trim() !== '') return candidate.trim();
  }
  return undefined;
}

export function shouldAutoRefreshProtocolEditorEdgeLabel(
  currentLabel: string | undefined,
  previousAutoLabel: string | undefined,
): boolean {
  const currentTrim = currentLabel?.trim() || undefined;
  const previousTrim = previousAutoLabel?.trim() || undefined;
  return currentTrim === undefined || currentTrim === previousTrim;
}

export function shouldDisplayProtocolEditorEdgeLabel(
  edge: ProtocolEdgeRecord,
  fromNode: ProtocolNodeRecord | undefined,
  toNode: ProtocolNodeRecord | undefined,
): boolean {
  if (toNode?.kind === 'answer' || toNode?.kind === 'snippet') {
    const effectiveLabel = deriveProtocolEditorEdgeLabel(toNode, edge.label);
    return effectiveLabel !== undefined && effectiveLabel.trim() !== '';
  }
  // Phase 50.1 EDGE-03 FIX: loop exit edges carry a user-authored "+"-prefixed label
  // that must be preserved regardless of the target node kind. A loop exit typically
  // points to a question/answer/text-block (not another loop node), so requiring
  // toNode.kind === 'loop' was stripping the label on save, making the edge unlabeled
  // and breaking the runner's exit-edge dispatch.
  if (fromNode?.kind === 'loop' && isProtocolEditorLoopExitLabel(edge.label)) {
    return true;
  }
  return false;
}

function deriveProtocolEditorEdgeLabel(
  targetNode: ProtocolNodeRecord | undefined,
  currentLabel: string | undefined,
): string | undefined {
  if (currentLabel !== undefined && currentLabel.trim() !== '') return currentLabel;
  return defaultProtocolEditorEdgeLabelForTarget(targetNode);
}

/* Phase 4D/4E — generate unique IDs */
function nodeUid(): string {
  return `node-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

function edgeUid(): string {
  return `edge-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

export function clampProtocolEditorZoom(zoom: number): number {
  if (!Number.isFinite(zoom)) return 1;
  return Math.min(MAX_ZOOM, Math.max(MIN_ZOOM, zoom));
}

export function screenDeltaToProtocolEditorDelta(delta: number, zoom: number): number {
  return delta / clampProtocolEditorZoom(zoom);
}

export function canCreateProtocolEditorEdge(
  edges: Pick<ProtocolEdgeRecord, 'fromNodeId' | 'toNodeId'>[],
  fromNodeId: string,
  toNodeId: string,
): 'ok' | 'self' | 'duplicate' {
  if (fromNodeId === toNodeId) return 'self';
  if (edges.some((edge) => edge.fromNodeId === fromNodeId && edge.toNodeId === toNodeId)) return 'duplicate';
  return 'ok';
}

export function removeProtocolEditorEdge(
  edges: ProtocolEdgeRecord[],
  edgeId: string,
): ProtocolEdgeRecord[] {
  return edges.filter((edge) => edge.id !== edgeId);
}

export function normalizeProtocolEditorSnippetFolderSelection(relativePath: string): string | undefined {
  const trimmed = relativePath.trim().replace(/^\/+|\/+$/g, '');
  return trimmed === '' ? undefined : trimmed;
}

/** Maximum configured bend radius for edge Q-curves. */
const CONFIGURED_MAX_BEND = 32;
/** Backward route exit/entry offset in pixels. */
const BACKWARD_OFFSET = 40;

function computeEdgeBend(
  rankDelta: number,
  normalDelta: number,
  forward: boolean,
): number {
  if (forward) {
    // Forward: first L segment is rankDelta/2 - bend (must be >= 0)
    // Middle L segment is |normalDelta| - 2*bend (must be >= 0)
    // The computed safe maximum is authoritative: applying a visual minimum above
    // this value reintroduces backtracking on very short doglegs.
    return Math.max(0, Math.min(
      rankDelta / 2,
      Math.abs(normalDelta) / 2,
      CONFIGURED_MAX_BEND,
    ));
  }
  // Backward: exit/entry offset constrains first/last L: BACKWARD_OFFSET - bend >= 0
  // Cross-direction constraint: L2 + L4 = |normalDelta| - 2*bend >= 0 → bend <= |normalDelta|/2
  // Conservative bound |normalDelta|/2 always ≤ actual L2/L4 constraint (TB adds 40-56px margin).
  return Math.max(0, Math.min(
    BACKWARD_OFFSET,
    Math.abs(normalDelta) / 2,
    CONFIGURED_MAX_BEND,
  ));
}

export function protocolEditorEdgeRoute(
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  direction: ProtocolEditorLayoutDirection = 'LR',
): ProtocolEditorEdgeRoute {
  const rankDelta = direction === 'TB' ? y2 - y1 : x2 - x1;
  const normalDelta = direction === 'TB' ? x2 - x1 : y2 - y1;
  const forward = rankDelta >= 0;
  const bend = computeEdgeBend(rankDelta, normalDelta, forward);

  if (forward) {
    if (direction === 'TB') {
      if (Math.abs(normalDelta) < 1) {
        return {
          d: `M ${x1} ${y1} L ${x2} ${y2}`,
          labelX: (x1 + x2) / 2,
          labelY: (y1 + y2) / 2 - 10,
        };
      }
      const midY = y1 + rankDelta / 2;
      return {
        d: roundedProtocolEditorOrthogonalPath([
          { x: x1, y: y1 },
          { x: x1, y: midY },
          { x: x2, y: midY },
          { x: x2, y: y2 },
        ], bend),
        labelX: (x1 + x2) / 2,
        labelY: midY - 10,
      };
    }

    const midX = x1 + rankDelta / 2;
    if (Math.abs(normalDelta) < 1) {
      return {
        d: `M ${x1} ${y1} L ${x2} ${y2}`,
        labelX: midX,
        labelY: y1 - 10,
      };
    }
    return {
      d: roundedProtocolEditorOrthogonalPath([
        { x: x1, y: y1 },
        { x: midX, y: y1 },
        { x: midX, y: y2 },
        { x: x2, y: y2 },
      ], bend),
      labelX: midX,
      labelY: (y1 + y2) / 2 - 10,
    };
  }

  if (direction === 'TB') {
    const routeX = Math.max(x1, x2) + Math.max(56, Math.abs(normalDelta) / 2 + 40);
    const exitY = y1 + 40;
    const entryY = y2 - 40;
    return {
      d: roundedProtocolEditorOrthogonalPath([
        { x: x1, y: y1 },
        { x: x1, y: exitY },
        { x: routeX, y: exitY },
        { x: routeX, y: entryY },
        { x: x2, y: entryY },
        { x: x2, y: y2 },
      ], bend),
      labelX: routeX + 14,
      labelY: (exitY + entryY) / 2,
    };
  }

  const routeY = Math.max(y1, y2) + Math.max(48, Math.abs(normalDelta) / 2 + 32);
  const exitX = x1 + 40;
  const entryX = x2 - 40;
  return {
    d: roundedProtocolEditorOrthogonalPath([
      { x: x1, y: y1 },
      { x: exitX, y: y1 },
      { x: exitX, y: routeY },
      { x: entryX, y: routeY },
      { x: entryX, y: y2 },
      { x: x2, y: y2 },
    ], bend),
    labelX: (exitX + entryX) / 2,
    labelY: routeY - 10,
  };
}

export class ProtocolEditorView extends ItemView {
  private readonly plugin: RadiProtocolPlugin;
  private protocolPath: string | null = null;
  private doc: ProtocolDocumentV1 | null = null;
  private rootEl: HTMLElement | null = null;
  private viewportEl: HTMLElement | null = null;
  private surfaceEl: HTMLElement | null = null;
  private svgEl: SVGSVGElement | null = null;
  private minimapEl: HTMLElement | null = null;
  private minimapSvgEl: SVGSVGElement | null = null;
  private minimapViewportEl: SVGRectElement | null = null;
  private minimapWorldBounds: { x: number; y: number; width: number; height: number } | null = null;
  private readonly nodeElementById = new Map<string, HTMLElement>();
  private readonly liveNodeGeometryById = new Map<string, ProtocolEditorLiveNodeGeometry>();
  private panState: PanState | null = null;

  private connectionDragState: ConnectionDragState | null = null;
  private viewportSaveTimer: number | null = null;
  private layoutDirection: ProtocolEditorLayoutDirection = 'LR';
  private zoom: number = 1;
  private loadGeneration = 0;

  constructor(leaf: WorkspaceLeaf, plugin: RadiProtocolPlugin) {
    super(leaf);
    this.plugin = plugin;
  }

  getViewType(): string { return PROTOCOL_EDITOR_VIEW_TYPE; }
  getDisplayText(): string { return this.plugin.i18n.t('protocolEditor.displayText'); }
  getIcon(): string { return 'workflow'; }

  async onOpen(): Promise<void> {
    this.renderShell();
  }

  async onClose(): Promise<void> {
    this.clearPendingViewportSave();
    this.rootEl = null;
    this.viewportEl = null;
    this.surfaceEl = null;
    this.svgEl = null;
    this.minimapEl = null;
    this.minimapSvgEl = null;
    this.minimapViewportEl = null;
    this.minimapWorldBounds = null;
    this.doc = null;
    this.protocolPath = null;
    this.panState = null;
    this.connectionDragState = null;
    this.nodeElementById.clear();
    this.liveNodeGeometryById.clear();
    document.body.removeClass('rp-protocol-editor-drag-active');
    document.body.removeClass('rp-protocol-editor-resize-active');
  }

  async loadProtocol(protocolPath: string): Promise<void> {
    const file = this.app.vault.getAbstractFileByPath(protocolPath);
    if (!(file instanceof TFile) || !file.path.endsWith('.rp.json')) {
      new Notice(this.plugin.i18n.t('protocolEditor.notProtocolFile'));
      return;
    }

    const doc = await this.plugin.protocolDocumentStore.read(file.path);
    if (doc === null) {
      new Notice(this.plugin.i18n.t('protocolEditor.loadFailed'));
      return;
    }

    this.loadGeneration++;
    this.protocolPath = file.path;
    this.doc = doc;
    this.layoutDirection = protocolEditorLayoutDirectionFromDocument(doc);
    this.zoom = clampProtocolEditorZoom(doc.viewport?.zoom ?? 1);
    this.renderShell();
    this.renderDocument();
  }

  private renderShell(): void {
    const container = this.containerEl.children[1] as HTMLElement | undefined;
    if (container === undefined) return;
    container.empty();
    this.rootEl = container.createDiv({ cls: 'rp-protocol-editor' });

    const workspace = this.rootEl.createDiv({ cls: 'rp-protocol-editor-workspace' });

    const floatingActions = workspace.createDiv({ cls: 'rp-protocol-editor-floating-actions' });
    const selfCheckBtn = floatingActions.createEl('button', {
      cls: 'rp-protocol-editor-floating-action',
      attr: {
        type: 'button',
        'aria-label': this.plugin.i18n.t('selfCheck.title'),
      },
    });
    setIcon(selfCheckBtn, 'list-checks');
    selfCheckBtn.addEventListener('click', () => this.openSelfCheckModal());

    const minimapToggleBtn = floatingActions.createEl('button', {
      cls: 'rp-protocol-editor-floating-action',
      attr: {
        type: 'button',
        'aria-label': this.plugin.i18n.t('protocolEditor.toggleMinimap'),
      },
    });
    setIcon(minimapToggleBtn, 'map');
    minimapToggleBtn.addEventListener('click', () => this.toggleMinimap());

    const autoLayoutVerticalBtn = floatingActions.createEl('button', {
      cls: 'rp-protocol-editor-floating-action',
      attr: {
        type: 'button',
        'aria-label': this.plugin.i18n.t('protocolEditor.autoLayoutVertical'),
      },
    });
    setIcon(autoLayoutVerticalBtn, 'layout');
    autoLayoutVerticalBtn.addEventListener('click', () => this.autoLayoutNodes('TB'));

    const autoLayoutHorizontalBtn = floatingActions.createEl('button', {
      cls: 'rp-protocol-editor-floating-action',
      attr: {
        type: 'button',
        'aria-label': this.plugin.i18n.t('protocolEditor.autoLayoutHorizontal'),
      },
    });
    setIcon(autoLayoutHorizontalBtn, 'layout');
    autoLayoutHorizontalBtn.addEventListener('click', () => this.autoLayoutNodes('LR'));

    workspace.createDiv({
      cls: 'rp-protocol-editor-canvas-title',
      text: this.doc?.title ?? this.plugin.i18n.t('protocolEditor.emptyTitle'),
    });
    this.viewportEl = workspace.createDiv({ cls: 'rp-protocol-editor-viewport' });
    this.viewportEl.setAttr('data-zoom', String(this.zoom));
    this.viewportEl.setAttr('data-layout-direction', this.layoutDirection);
    this.surfaceEl = this.viewportEl.createDiv({ cls: 'rp-protocol-editor-surface' });
    this.svgEl = this.viewportEl.createSvg('svg', { cls: 'rp-protocol-editor-edges' });

    if (this.doc !== null) {
      this.minimapEl = workspace.createDiv({ cls: 'rp-protocol-editor-minimap' });
      this.minimapEl.setAttr('role', 'button');
      this.minimapEl.setAttr('tabindex', '0');
      this.minimapEl.setAttr('aria-label', this.plugin.i18n.t('protocolEditor.minimapLabel'));
      this.minimapSvgEl = this.minimapEl.createSvg('svg', {
        attr: {
          class: 'rp-protocol-editor-minimap-svg',
          viewBox: `0 0 ${DEFAULT_VIEWPORT_WIDTH} ${DEFAULT_VIEWPORT_HEIGHT}`,
          preserveAspectRatio: 'none',
        },
      }) as SVGSVGElement;
      const zoomIndicator = this.minimapEl.createDiv({ cls: 'rp-protocol-editor-zoom-indicator' });
      zoomIndicator.setText(`${Math.round(this.zoom * 100)}%`);
    } else {
      this.minimapEl = null;
      this.minimapSvgEl = null;
      this.minimapViewportEl = null;
      this.minimapWorldBounds = null;
    }

    this.applyZoom();
    this.bindViewportControls();
    this.bindMinimapControls();
    this.restoreViewportState();

    if (this.doc === null) {
      this.surfaceEl.createDiv({
        cls: 'rp-protocol-editor-empty',
        text: this.plugin.i18n.t('protocolEditor.emptyState'),
      });
    }
  }

  private createProtocolEditorNode(kind: RPNodeKind | null, x: number, y: number): ProtocolNodeRecord {
    const defaults = (kind !== null && NODE_KIND_DEFAULTS[kind])
      ? NODE_KIND_DEFAULTS[kind]
      : { kind: null as RPNodeKind | null, fields: {} };

    const text = defaults.text ?? (kind !== null && kind !== 'start' ? this.plugin.i18n.t(`protocolEditor.defaultNodeText.${kind}`) : undefined);
    return {
      id: nodeUid(),
      kind: defaults.kind,
      x: Math.round(x),
      y: Math.round(y),
      width: DEFAULT_NODE_WIDTH,
      height: DEFAULT_NODE_HEIGHT,
      color: defaults.color ?? defaultColorForProtocolEditorNodeKind(defaults.kind),
      text,
      fields: { ...defaults.fields },
    };
  }

  private setNodeKindPickerBusy(modalEl: HTMLElement, busy: boolean): void {
    modalEl.toggleClass('is-saving', busy);
    for (const button of Array.from(modalEl.querySelectorAll('button'))) {
      (button as HTMLButtonElement).disabled = busy;
    }
  }

  private addNodeAtWorldPoint(
    kind: RPNodeKind | null,
    x: number,
    y: number,
    options: ProtocolEditorCreateNodeOptions = {},
  ): void {
    if (this.doc === null || this.protocolPath === null) {
      options.onCreateAbandoned?.();
      return;
    }

    const newNode = this.createProtocolEditorNode(kind, x, y);
    const protocolPath = this.protocolPath;
    const generation = this.loadGeneration;

    void this.plugin.protocolDocumentStore.update(protocolPath, (existing) => {
      if (existing === null) protocolMissingFileError();
      return { ...existing, nodes: [...existing.nodes, newNode], viewport: this.currentViewportState(), updatedAt: new Date().toISOString() };
    }).then((updated) => {
      try {
        if (this.protocolPath !== protocolPath || this.loadGeneration !== generation) {
          options.onCreateAbandoned?.();
          return;
        }
        const createdNode = this.applyCreatedProtocolDocument(updated, newNode.id) ?? newNode;
        this.openEditModal(createdNode, { autofocusFirstTextField: true });
        options.onEditModalOpened?.();
        new Notice(this.plugin.i18n.t('protocolEditor.nodeCreated'));
      } catch (err) {
        console.error('[RadiProtocol] Failed to update Protocol Editor UI after creating node:', err);
        options.onCreateFailed?.();
        new Notice(this.plugin.i18n.t('protocolEditor.saveFailed', { error: String(err) }));
      }
    }, (err) => {
      options.onCreateFailed?.();
      new Notice(this.plugin.i18n.t('protocolEditor.saveFailed', { error: String(err) }));
    });
  }

  private openNodeKindPickerAtWorldPoint(x: number, y: number): void {
    if (this.doc === null || this.protocolPath === null) return;
    const t = this.plugin.i18n.t.bind(this.plugin.i18n);
    const modalEl = document.body.createDiv({ cls: 'rp-protocol-editor-modal-backdrop' });
    const modal = modalEl.createDiv({ cls: 'rp-protocol-editor-modal rp-protocol-editor-node-kind-modal' });
    const header = modal.createDiv({ cls: 'rp-protocol-editor-modal-header' });
    header.createEl('h3', { text: t('protocolEditor.chooseNodeType') });
    const closeBtn = header.createEl('button', { cls: 'rp-protocol-editor-modal-close', text: '✕', attr: { 'aria-label': t('protocolEditor.close') } });
    let isCreating = false;
    const closeModal = (options?: { restoreFocus?: boolean }) => {
      modalEl.remove();
      if (options?.restoreFocus !== false) this.restoreEditorFocus();
    };
    const beginCreate = () => {
      isCreating = true;
      this.setNodeKindPickerBusy(modalEl, true);
    };
    const restorePicker = () => {
      isCreating = false;
      this.setNodeKindPickerBusy(modalEl, false);
    };
    closeBtn.addEventListener('click', () => {
      if (isCreating) return;
      closeModal();
    });

    const body = modal.createDiv({ cls: 'rp-protocol-editor-modal-body' });
    const grid = body.createDiv({ cls: 'rp-protocol-editor-node-kind-grid' });
    for (const kind of EDITABLE_NODE_KINDS) {
      const btn = grid.createEl('button', {
        cls: 'rp-protocol-editor-node-kind-choice',
        text: t(`protocolEditor.nodeKind.${kind}`),
      });
      btn.setAttr('data-node-kind', kind);
      btn.addEventListener('click', () => {
        if (isCreating) return;
        beginCreate();
        this.addNodeAtWorldPoint(kind, x, y, {
          onEditModalOpened: () => closeModal({ restoreFocus: false }),
          onCreateAbandoned: () => closeModal(),
          onCreateFailed: restorePicker,
        });
      });
    }
    modalEl.addEventListener('click', (e) => {
      if (isCreating) return;
      if (e.target === modalEl) closeModal();
    });
  }

