/* Phase 51 PICKER-02 — SnippetTreePicker styles. */
/* See docs/ARCHITECTURE-NOTES.md#snippet-node-binding-and-picker */
/* Class prefix: rp-stp-* (distinct from rp-snippet-* runner picker classes). */
/* Plan 02 owns this file end-to-end — host wrappers for Plans 03/04/05 included here. */

.rp-stp-root {
  /* display/flex/gap migrated to .rp-stack-lg utility (Phase 80) */
  gap: var(--size-2-3);
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
}

/* Beta 9 follow-up — keep drill navigation from resizing inline/modals when
 * switching between folders with different folder/file counts. */
.rp-stp-body {
  display: flex;
  flex-direction: column;
  gap: var(--size-2-3);
  min-height: 280px;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
}

.rp-stp-modal-host .rp-stp-body {
  height: 360px;
}

.rp-stp-inline-host .rp-stp-body {
  flex: 1 1 auto;
  min-height: 0;
  height: 100%;
}

.rp-stp-editor-host .rp-stp-body {
  min-height: 240px;
}

.rp-stp-body .rp-stp-list {
  flex: 1 1 auto;
}

.rp-stp-inline-host .rp-stp-root {
  display: flex;
  flex: 1 1 auto;
  flex-direction: column;
  min-height: 0;
  height: 100%;
}

.rp-stp-search {
  display: flex;
  align-items: center;
  width: 100%;
  min-width: 0;
}

.rp-stp-search-input {
  width: 100%;
  box-sizing: border-box;
  min-height: 28px;
}

.rp-stp-breadcrumb {
  display: flex;
  align-items: flex-start;
  gap: var(--size-2-1);
  width: 100%;
  min-width: 0;
  font-size: var(--font-ui-small);
  color: var(--text-muted);
  flex-wrap: wrap;
  line-height: 1.3;
}

.rp-stp-breadcrumb-label {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.rp-stp-crumb[aria-current="location"] {
  color: var(--text-normal);
  font-weight: var(--font-semibold);
}

.rp-stp-crumb,
.rp-stp-up-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  height: auto;
  min-width: 0;
  padding: 0 var(--size-2-2);
  border: 1px solid transparent;
  border-radius: var(--radius-s);
